/* Life Lately · interface pessoal, mobile-first. Dependências: core.js e storage.js. */
'use strict';
const $=id=>document.getElementById(id),esc=(v='')=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={home:'M3 10 12 3l9 7M5 9v11h5v-6h4v6h5V9',income:'M5 18 19 4M7 4h12v12M4 22h16',organize:'M3 8h18v12H3zM3 8V5a2 2 0 0 1 2-2h13v5M17 12h4v5h-4a2.5 2.5 0 0 1 0-5Z',goals:'M21 12a9 9 0 1 1-9-9M17 12a5 5 0 1 1-5-5M12 12l8-8M17 3h4v4',debts:'M3 5h18v15H3zM3 10h18M7 15h4',plus:'M12 5v14M5 12h14',chevron:'m9 5 7 7-7 7',back:'m14 5-7 7 7 7',close:'m6 6 12 12M6 18 18 6',check:'m5 12 4 4L19 6',arrow:'M4 12h16m-6-6 6 6-6 6',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8ZM10 3h4l1 3 3 1 3 3v4l-3 1-1 3-3 3h-4l-1-3-3-1-3-3v-4l3-1 1-3Z',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3Z',lock:'M6 10h12v11H6zM8 10V7a4 4 0 0 1 8 0v3M12 14v3',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',upload:'M12 16V4m-5 5 5-5 5 5M4 16v5h16v-5',calendar:'M4 5h16v16H4zM4 10h16M8 3v4m8-4v4',more:'M5 12h.01M12 12h.01M19 12h.01',chart:'M4 21V3m0 18h17M8 17v-5m5 5V7m5 10V4',transfer:'M3 7h17m-4-4 4 4-4 4M21 17H4m4-4-4 4 4 4',info:'M12 16v-4m0-4h.01M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0Z',shield:'m12 3 8 3v6c0 4-8 9-8 9s-8-5-8-9V6l8-3Zm-4 9 3 3 5-6',refresh:'M20 7a9 9 0 0 0-15-1L3 9m0-6v6h6M4 17a9 9 0 0 0 15 1l2-3m0 6v-6h-6',wallet:'M4 5h16v15H4zM16 10h4v5h-4a2.5 2.5 0 0 1 0-5Z',coins:'M12 3c5 0 9 2 9 4s-4 4-9 4-9-2-9-4 4-4 9-4ZM3 7v10c0 2 4 4 9 4s9-2 9-4V7M3 12c0 2 4 4 9 4s9-2 9-4',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Zm13 0a3 3 0 1 1-6 0 3 3 0 0 1 6 0Z',archive:'M3 4h18v5H3zM5 9v11h14V9M10 13h4',phone:'M7 2h10v20H7zM11 18h2'};
const icon=name=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.spark}"/></svg>`;
const brand=(kind='full')=>`<span class="ll-brand ll-brand-${kind==='full'?'full':'compact'}"><span class="ll-brand-symbol" aria-hidden="true"><i></i><i></i><i></i></span><span class="ll-brand-name">life lately<span class="ll-brand-dot" aria-hidden="true">.</span></span></span>`;
const btn=(text,action,id='',cls='primary',extra='')=>`<button type="button" class="${cls}" data-action="${action}" ${id?`data-id="${esc(id)}"`:''} ${extra}>${text}</button>`;
const arrow=()=>`<span class="chev" aria-hidden="true">${icon('chevron')}</span>`;
const navs=[['overview','home','Início'],['income','income','Ganhos'],['organize','organize','Organizar'],['goals','goals','Metas'],['debts','debts','Compromissos']];
let state=null,page='overview',busy=false,modalBack=null,opener=null,installPrompt=null,swWaiting=null,monthFilter=LL.today().slice(0,7),toastTimer,hiddenSince=0,orphanPassword='',activeStore=LLStore,accessMode='local',cloudUser=null;
const CLOUD_LOCK_KEY='life-lately-cloud-locked-v1';
const money=v=>LL.fmt(state||LL.empty(),v),compactMoney=v=>LL.fmt(state||LL.empty(),v,true);
const currencySymbol=()=>LL.CURRENCIES[state?.preferences.currency||'BRL'][1];
const numText=v=>Number(v||0).toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2});
const pct=v=>Number(v||0).toLocaleString('pt-BR',{maximumFractionDigits:2})+'%';
const dateText=(d,full=false)=>LL.validDate(d)?new Date(d+'T12:00:00').toLocaleDateString('pt-BR',full?{day:'2-digit',month:'2-digit',year:'numeric'}:{day:'2-digit',month:'short',...(d.slice(0,4)!==LL.today().slice(0,4)?{year:'numeric'}:{})}):'Sem prazo';
function deadline(t){if(t.paused)return 'Toque para replanejar';if(t.done)return t.used>0?'Atendido neste ciclo':'Valor completo';if(!t.date)return 'Sem prazo';if(t.days<0)return `${Math.abs(t.days)} ${t.days===-1?'dia':'dias'} em atraso`;if(t.days===0)return 'Até hoje';if(t.days===1)return 'Até amanhã';return `Até ${dateText(t.date)}`;}
function toast(text){$('toast').textContent=text;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),2600);}
function setError(err){const e=$('dialogError')||$('accessError');if(e){e.textContent=typeof err==='string'?err:err.message||'Não foi possível concluir.';e.hidden=false;e.scrollIntoView({block:'nearest'});}else toast(err.message||String(err));}
function field(name,label,value='',type='text',extra=''){return `<div class="field"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}></div>`;}
function moneyField(name,label,value='',big=false,extra=''){const display=value===''?'':numText(value);return `<div class="field"><label for="f-${name}">${label} <span class="sr-only">em ${esc(LL.CURRENCIES[state?.preferences.currency||'BRL'][0])}</span></label><div class="money-input-wrap ${big?'big':''}"><span class="money-prefix" aria-hidden="true">${currencySymbol()}</span><input id="f-${name}" name="${name}" type="text" inputmode="decimal" data-money autocomplete="off" value="${esc(display)}" placeholder="0,00" style="--money-pad:${34+currencySymbol().length*9}px" ${extra}></div></div>`;}
function optionalDetails(content,label='Mais detalhes'){return `<details class="quiet-details"><summary>${label}</summary>${content}</details>`;}
function getAmount(form,name){const n=LL.parseMoney(new FormData(form).get(name));if(n<0)throw Error('Use um valor maior ou igual a zero.');return n;}
function footer(label){return `<div class="dialog-foot"><button type="submit" class="primary full">${label}</button></div>`;}
function moneySetup(root=document){root.querySelectorAll('[data-money]:not([data-ready])').forEach(el=>{el.dataset.ready='1';el.addEventListener('focus',()=>{el.select();});el.addEventListener('input',()=>el.setCustomValidity(''));el.addEventListener('blur',()=>{try{if(el.value.trim())el.value=numText(LL.parseMoney(el.value));el.setCustomValidity('');}catch(e){el.setCustomValidity(e.message);}});});}
function modal(title,body,{back=null,focus=null}={}){
 clearTimeout(toastTimer);$('toast').classList.remove('visible');
 const d=$('dialog');if(!d.open)opener=document.activeElement;
 modalBack=back;
 $('dialogRoot').innerHTML=`<header class="dialog-head">${back?btn(icon('back'),'modal-back','','icon-button','aria-label="Voltar"'):''}<h2 id="dialogTitle" tabindex="-1">${esc(title)}</h2>${btn(icon('close'),'close','','icon-button','aria-label="Fechar"')}</header><div class="dialog-body"><div id="dialogError" class="error" role="alert" hidden></div>${body}</div>`;
 moneySetup(d);
 if(!d.open)d.showModal();document.body.style.overflow='hidden';d.scrollTop=0;
 const focusEl=focus?d.querySelector(focus):$('dialogTitle');focusEl?.focus({preventScroll:true});
}
function closeModal(){if(busy)return;$('dialog').close();$('dialogRoot').innerHTML='';modalBack=null;document.body.style.overflow='';if(opener?.isConnected)opener.focus({preventScroll:true});else $('view')?.focus({preventScroll:true});}
function bindForm(id,handler){$(id).addEventListener('submit',async e=>{e.preventDefault();if(busy)return;const err=$('dialogError')||$('accessError');if(err)err.hidden=true;try{await handler(e.currentTarget);}catch(e){setError(e);}});}
async function commit(change,{message='Salvo.',after=null,close=true}={}){
 if(busy)return;busy=true;const button=$('dialog')?.querySelector('button[type=submit]');const old=button?.textContent;if(button){button.disabled=true;button.textContent='Salvando…';}
 try{const draft=LL.clone(state),result=change(draft);LL.validate(draft);await activeStore.save(draft);state=draft;busy=false;render();if(close)closeModal();if(after)after(result);else if(message)toast(message);return result;}
 catch(e){busy=false;if(button?.isConnected){button.disabled=false;button.textContent=old;}throw e;}
}
function emptyBox(symbol,title,caption,action='',label='Começar',id=''){return `<div class="empty"><span class="empty-icon" aria-hidden="true">${symbol}</span><b>${title}</b>${caption?`<p>${caption}</p>`:''}${action?btn(label,action,id):''}</div>`;}
function head(title,caption='',action=''){return `<div class="page-head"><div><h1>${title}</h1>${caption?`<p>${caption}</p>`:''}</div>${action}</div>`;}
function showPage(next){if(!state)return;if($('dialog').open)closeModal();clearTimeout(toastTimer);$('toast').classList.remove('visible');page=next;render();window.scrollTo({top:0,behavior:'instant'});}
function renderShell(){
 const navHTML=navs.map(([id,ic,name])=>`<button type="button" class="nav-item ${page===id?'active':''}" data-action="nav" data-id="${id}" ${page===id?'aria-current="page"':''}>${icon(ic)}<span>${name}</span>${id==='organize'&&LL.pendingCents(state)>0?'<span class="attention-dot" aria-hidden="true"></span>':''}</button>`).join('');
 $('mobileNav').innerHTML=navHTML;
 $('sidebar').innerHTML=`<button type="button" class="brand" data-action="nav" data-id="overview" aria-label="Life Lately, início">${brand('compact')}</button><nav class="sidebar-nav" aria-label="Navegação">${navHTML}</nav><div class="sidebar-bottom">${btn(icon('settings')+'Configurações','nav','settings','')}${btn(icon('lock')+'Bloquear','lock','','')}<span class="sidebar-footer">Feito para o seu ritmo.</span></div>`;
 const connection=accessMode==='cloud'?`<span class="fine sync-state"><i class="offline-dot ${navigator.onLine?'online':''}"></i> ${navigator.onLine?'Nuvem':'Offline'}</span>`:accessMode==='guest'?'<span class="fine">Modo conhecer</span>':!navigator.onLine?'<span class="fine"><i class="offline-dot"></i> Offline</span>':'';
 $('topbar').innerHTML=`<button type="button" class="brand" data-action="nav" data-id="overview" aria-label="Life Lately, início">${brand('compact')}</button><span class="desktop-subtitle">Um espaço para cuidar do seu dinheiro.</span><div class="flex">${connection}${btn(esc((state.profile.name||'S').slice(0,1).toUpperCase()),'nav','settings','avatar','aria-label="Abrir configurações"')}</div>`;
}
function render(){if(!state)return;renderShell();const screens={overview:renderOverview,income:renderIncome,organize:renderOrganize,goals:renderGoals,debts:renderDebts,settings:renderSettings};$('view').innerHTML=(screens[page]||renderOverview)();document.title=`${({overview:'Início',income:'Ganhos',organize:'Organizar',goals:'Metas',debts:'Compromissos',settings:'Configurações'})[page]} · Life Lately`;}
function sortedPockets(){return LL.cats(state).sort((a,b)=>{if(a.role==='free')return 1;if(b.role==='free')return -1;const ta=LL.target(state,a),tb=LL.target(state,b);if(ta.done!==tb.done)return ta.done?1:-1;return (ta.date||'9999').localeCompare(tb.date||'9999');});}
function pocketCard(c,{asGoal=false,mini=false}={}){
 const t=LL.target(state,c),p=LL.allocation(state,100),share=(p.shares[c.id]||0)/100;
 const progress=t.amount?Math.min(100,Math.max(0,t.covered/t.amount*100)):0;
 const roleBadge=LL.linkedDebts(state,c.id).length?'Compromisso':c.role==='goal'?'Meta':c.role==='free'?'Seu livre':'';
 if(mini)return `<button type="button" class="row-card" data-action="pocket" data-id="${c.id}"><span class="tile-icon" style="background:${c.color}20">${esc(c.icon)}</span><span class="grow"><span class="name">${esc(c.label)}</span><small>${esc(deadline(t))}</small></span><span class="end"><strong>${money(t.saved)}</strong><small>${t.amount?`de ${money(t.amount)}`:'disponíveis'}</small></span>${arrow()}</button>`;
 return `<button type="button" class="tap-card pocket-card ${asGoal?'goal-card':''} ${c.role==='free'?'muted-card':''}" data-action="${asGoal?'goal-open':'pocket'}" data-id="${c.id}" style="--category:${c.color}"><span class="top"><span class="tile-icon" style="background:${c.color}20">${esc(c.icon)}</span><span class="grow"><span class="name">${esc(c.label.replace(/^Meta · /,''))}</span><span class="deadline ${t.days<0&&t.remaining>0?'text-danger':''}">${esc(deadline(t))}</span></span>${arrow()}</span><span class="balance-line"><strong>${money(t.saved)}</strong><span>${t.amount?`de ${money(t.amount)}`:'disponíveis'}</span></span>${t.amount?`<span class="progress-wrap"><span class="track" aria-hidden="true"><span style="width:${progress}%"></span></span><span class="bottom"><span>${t.done?(t.used>0?'✓ Atendido neste ciclo':'✓ Valor completo'):`Faltam ${money(t.remaining)}`}</span><span>${pct(progress)}</span></span></span>`:''}<span class="bottom"><span class="badge ${t.done?'green':roleBadge?'rose':''}">${c.planningPaused?'Sem plano':t.done?(t.linked.length?'Pronto para quitar':'Completo'):c.recurrence==='monthly'?'Todo mês':roleBadge||'Planejado'}</span><span>${t.done?'Excedente → Livre':p.pending===10000?'Defina o plano':`${money(share)} a cada ${compactMoney(100)}`}</span></span></button>`;
}
function incomeRow(t){const pending=Math.max(0,LL.cents(t.value)-LL.allocatedCents(t));return `<button type="button" class="row-card" data-action="income-open" data-id="${esc(t.id)}"><span class="tile-icon" style="background:#edf4eb;color:var(--green)">${icon('income')}</span><span class="grow"><span class="name">${esc(t.description)}</span><small>${dateText(t.date)}${pending>0?' · a separar':''}</small></span><span class="end"><strong class="income-amount">+ ${money(t.value)}</strong><small>${esc(t.type||'Ganho')}</small></span>${arrow()}</button>`;}
function weekChart(){
 const dt=new Date(LL.today()+'T12:00:00'),start=new Date(dt);start.setDate(start.getDate()-(start.getDay()+6)%7);
 const labels=['S','T','Q','Q','S','S','D'],days=[];for(let i=0;i<7;i++){const d=new Date(start);d.setDate(d.getDate()+i);const iso=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;days.push({iso,label:labels[i],value:state.transactions.filter(t=>t.date===iso).reduce((a,t)=>a+LL.cents(t.value),0)/100});}
 const max=Math.max(1,...days.map(x=>x.value)),total=days.reduce((a,x)=>a+LL.cents(x.value),0)/100;
 const short=n=>n>=1000?(n/1000).toLocaleString('pt-BR',{maximumFractionDigits:1})+' mil':n.toLocaleString('pt-BR',{maximumFractionDigits:2});
 return `<article class="card week-card"><div class="between"><h2>Esta semana</h2><strong class="money text-rose">${money(total)}</strong></div><div class="weekly-bars" role="img" aria-label="Ganhos da semana: ${days.map(d=>`${dateText(d.iso)}: ${money(d.value)}`).join('; ')}">${days.map(d=>`<div class="bar-col" aria-hidden="true"><span class="bar-value">${d.value?short(d.value):'—'}</span><span class="bar ${d.value?'':'zero'} ${d.iso===LL.today()?'today':''}" style="height:${d.value?Math.max(9,d.value/max*100):5}px"></span><span class="bar-day">${d.label}</span></div>`).join('')}</div></article>`;
}
function activityList(items,limit=6){if(!items.length)return '<p class="fine">Sem movimentações ainda.</p>';return items.slice(0,limit).map(a=>{const type=a.targetType||'',ic=type==='debt'?'debts':type==='income'?'income':type==='allocation'?'organize':type==='planning'?'calendar':'transfer';return `<div class="history-row"><span class="text-rose">${icon(ic)}</span><div><b>${esc(a.title||'Movimentação')}</b><small>${dateText(a.date)}${a.note?` · ${esc(a.note)}`:''}</small></div><span class="history-money">${a.action==='configure'||a.action==='archive'||a.targetType==='planning'?'':(Number(a.delta)<0?'−':Number(a.delta)>0?'+':'')+money(Math.abs(Number(a.delta)||0))}</span></div>`;}).join('');}
function renderOverview(){
 const s=LL.summary(state),name=(state.profile.name||'').split(' ')[0],pockets=sortedPockets().filter(c=>LL.target(state,c).amount>0),next=pockets.filter(c=>LL.target(state,c).remaining>0).slice(0,3);
 let nudge='';
 if(!pockets.length)nudge=`<button class="nudge" data-action="new-pocket"><span class="symbol">🏠</span><span class="grow"><b>O que você precisa pagar ou juntar?</b><small>Comece pelo seu primeiro cofrinho.</small></span>${arrow()}</button>`;
 else if(s.pending>0)nudge=`<button class="nudge" data-action="apply"><span class="symbol">✨</span><span class="grow"><b>${money(s.pending)} esperando um destino</b><small>Veja a divisão e confirme.</small></span>${arrow()}</button>`;
 else if(!state.transactions.length)nudge=`<button class="nudge" data-action="new-income"><span class="symbol">↗</span><span class="grow"><b>Os cofrinhos já estão prontos.</b><small>Agora registre o primeiro ganho.</small></span>${arrow()}</button>`;
 return `<div class="greeting"><span class="kicker">Seu dinheiro, no seu ritmo</span><div class="between"><h1>${name?`Oi, ${esc(name)}.`:'Oi. Vamos começar?'}</h1>${btn(icon('calendar')+' '+esc(monthText(LL.planningMonth(state),true)),'month-rollover','','month-chip month-button','aria-label="Abrir virada de mês"')}</div></div><div class="hero-grid"><article class="hero-balance"><span class="label">${LL.planningMonth(state)===LL.today().slice(0,7)?'Entrou neste mês':'Entrou em '+monthName(LL.planningMonth(state))}</span><div class="amount xl">${money(s.monthIncome)}</div><div class="hero-detail">${state.transactions.length?`Total recebido: ${money(s.lifetimeIncome)}`:'Um ganho de cada vez.'}</div>${btn(icon('plus')+' Ganhei','new-income','','primary full')}</article><div class="stats-row"><button class="tap-card" data-action="nav" data-id="organize"><span class="stat-top"><span class="label">Nos cofrinhos</span>${icon('organize')}</span><span class="amount">${money(s.pockets)}</span></button><button class="tap-card" data-action="${s.pending?'apply':'pocket'}" data-id="${LL.cats(state).find(c=>c.role==='free')?.id||''}"><span class="stat-top"><span class="label">${s.pending?'A separar':'Livre para você'}</span>${icon(s.pending?'transfer':'spark')}</span><span class="amount ${s.pending?'text-rose':'text-green'}">${money(s.pending||s.free)}</span></button></div></div>${nudge}${LL.planningMonth(state)<LL.today().slice(0,7)?`<button class="nudge month-nudge" data-action="month-rollover"><span class="symbol">${icon('calendar')}</span><span class="grow"><b>Vamos virar o mês?</b><small>Seu saldo e seus planos seguem com você.</small></span>${arrow()}</button>`:''}<div class="dashboard-columns"><section class="section"><div class="section-heading"><h2>Seus próximos planos</h2>${btn('Ver todos '+icon('arrow'),'nav','organize','link-button')}</div><div class="list">${next.length?next.map(c=>pocketCard(c,{mini:true})).join(''):pockets.length?'<div class="card tone-pink"><b>Todos os valores estão separados. ✨</b><p class="fine">Os cofrinhos continuam em Organizar.</p></div>':'<div class="empty quiet-empty"><span class="empty-icon" aria-hidden="true">🌷</span><b>Um lugar para cada plano.</b></div>'}</div></section><section class="section">${weekChart()}</section></div><section class="section"><div class="section-heading"><h2>Últimos ganhos</h2>${btn('Ver todos '+icon('arrow'),'nav','income','link-button')}</div><div class="list">${state.transactions.length?[...state.transactions].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,3).map(incomeRow).join(''):'<p class="fine">Seu primeiro ganho aparece aqui.</p>'}</div></section>`;
}
function freeBanner(){const f=LL.cats(state).find(c=>c.role==='free'&&LL.pocket(state,c.id)>0);return f?`<button type="button" class="free-banner" data-action="free-distribute" data-id="${esc(f.id)}"><span class="tile-icon">${icon('transfer')}</span><span class="grow"><small>Livre para redistribuir</small><strong>${money(LL.pocket(state,f.id))}</strong></span><span class="free-banner-action">Distribuir ${icon('arrow')}</span></button>`:'';}
function renderOrganize(){const s=LL.summary(state),forecast=LL.forecast(state),mode=state.preferences.allocationMode;
 return head('Seus cofrinhos.','Organizar',btn(icon('plus'),'new-pocket','','secondary compact','aria-label="Criar cofrinho"'))+`${planningToolbar()}<div class="balance-strip"><div><span class="label">Total nos cofrinhos</span><div class="amount">${money(s.pockets)}</div></div>${s.free?`<div class="small-balance"><span class="label">Livre</span><div class="money text-green"><b>${money(s.free)}</b></div></div>`:''}</div>${s.pending>0?`<div class="pending-banner"><div class="grow"><small>Ainda sem destino</small><strong>${money(s.pending)}</strong></div>${btn('Separar '+icon('arrow'),'apply','','primary')}</div>`:''}${freeBanner()}<button class="mode-card" data-action="allocation"><span class="mode-icon">${icon(mode==='manual'?'organize':'spark')}</span><span class="grow"><b>Divisão ${mode==='manual'?'manual':'automática'}</b><small>${mode==='manual'?'Você escolhe as porcentagens.':'Pelo que falta e pelo prazo.'}</small></span>${arrow()}</button>${forecast.late?'<div class="alert-inline">Há um prazo vencido. Ele continua na divisão; toque no cofrinho para revisar.</div>':forecast.shortfall?`<div class="alert-inline">O ritmo dos seus prazos está acima da renda que você informou. ${btn('Ver plano','allocation','','link-button')}</div>`:''}<div class="pocket-grid three">${sortedPockets().map(c=>pocketCard(c)).join('')}${LL.cats(state).length<=1?btn(icon('plus')+' Criar meu cofrinho','new-pocket','','new-tile'):''}</div><div class="section-heading section">${btn(icon('calendar')+' Histórico do planejamento','planning-history','','link-button')}${btn(icon('archive'),'archives','','icon-button','aria-label="Ver arquivados"')}</div>`;
}
function heatmap(){const [y,m]=monthFilter==='all'?LL.today().slice(0,7).split('-').map(Number):monthFilter.split('-').map(Number),last=new Date(y,m,0).getDate(),offset=(new Date(y,m-1,1).getDay()+6)%7;const amounts=Array.from({length:last},(_,i)=>{const date=`${y}-${String(m).padStart(2,'0')}-${String(i+1).padStart(2,'0')}`;return{day:i+1,date,value:state.transactions.filter(t=>t.date===date).reduce((a,t)=>a+LL.cents(t.value),0)/100};}),max=Math.max(1,...amounts.map(a=>a.value));return `<article class="card"><h2>Seu mês, dia a dia</h2><div class="heat-weekdays">${['S','T','Q','Q','S','S','D'].map(t=>`<span>${t}</span>`).join('')}</div><div class="heatmap">${'<span></span>'.repeat(offset)}${amounts.map(a=>`<button class="heat ${a.value?(a.value/max>.66?'l3':a.value/max>.33?'l2':'l1'):''}" data-action="day" data-id="${a.date}" aria-label="${dateText(a.date)}: ${money(a.value)}">${a.day}</button>`).join('')}</div><p class="heat-legend">Mais cor, mais dinheiro entrou.</p></article>`;}
function renderIncome(){const months=[...new Set([LL.planningMonth(state),LL.today().slice(0,7),...state.transactions.map(t=>t.date.slice(0,7))])].sort().reverse(),items=[...state.transactions].filter(t=>monthFilter==='all'||t.date.startsWith(monthFilter)).sort((a,b)=>b.date.localeCompare(a.date)),total=items.reduce((a,t)=>a+LL.cents(t.value),0)/100;
 return head('O que entrou.','Cada ganho conta.',btn(icon('plus')+' Ganhei','new-income','','primary compact'))+`<div class="income-summary"><div><span class="label">${monthFilter==='all'?'Total recebido':'Recebido no mês'}</span><div class="amount">${money(total)}</div></div><select id="monthFilter" class="input-filter" aria-label="Período dos ganhos"><option value="all" ${monthFilter==='all'?'selected':''}>Todo o período</option>${months.map(m=>`<option value="${m}" ${monthFilter===m?'selected':''}>${new Date(m+'-01T12:00:00').toLocaleDateString('pt-BR',{month:'short',year:'numeric'})}</option>`).join('')}</select></div><div class="income-main-grid"><section><div class="list">${items.length?items.map(incomeRow).join(''):emptyBox('💸','Ainda não entrou nada.','Quando receber, é só tocar em Ganhei.','new-income','Registrar ganho')}</div></section><section class="section">${heatmap()}</section></div>`;
}
function incomeTargetCard(key){const target=state.goals[key],now=new Date(LL.today()+'T12:00:00'),start=new Date(now);start.setDate(start.getDate()-(start.getDay()+6)%7);const startISO=`${start.getFullYear()}-${String(start.getMonth()+1).padStart(2,'0')}-${String(start.getDate()).padStart(2,'0')}`;const amount=state.transactions.filter(t=>key==='monthly'?t.date.startsWith(LL.planningMonth(state)):t.date>=startISO&&t.date<=LL.today()).reduce((a,t)=>a+LL.cents(t.value),0)/100;return `<button class="tap-card" data-action="income-target" data-id="${key}"><span class="label">${key==='monthly'?'Em '+monthName(LL.planningMonth(state)):'Na semana'}</span><strong>${target?money(target):'Definir valor'}</strong><span class="fine">${target?`${money(amount)} recebidos`:'Quanto pretende ganhar?'}</span>${target?`<span class="track" style="margin-top:10px"><span style="width:${Math.min(100,amount/target*100)}%"></span></span>`:''}</button>`;}
function renderGoals(){const goals=LL.cats(state).filter(c=>c.role==='goal'&&!c.planningPaused&&c.targetAmount>0);return head('Seus planos.','Metas',btn(icon('plus'),'new-goal','','secondary compact','aria-label="Criar meta"'))+`<div class="pocket-grid">${goals.length?goals.map(c=>pocketCard(c,{asGoal:true})).join(''):emptyBox('🎯','Qual é o seu próximo sonho?','Escolha o valor. Dê um prazo. O cofrinho vem junto.','new-goal','Criar minha meta')}</div><section class="section"><div class="section-heading"><h2>Quanto quero ganhar</h2><span class="fine">Opcional</span></div><div class="income-targets">${incomeTargetCard('monthly')}${incomeTargetCard('weekly')}</div></section>`;}

function debtCard(d){
 const f=LL.debtFunding(state,d),days=LL.daysTo(d.due);
 return `<button type="button" class="tap-card pocket-card debt-card ${f.ready?'debt-ready':''}" data-action="debt-open" data-id="${esc(d.id)}" style="--category:#748172"><span class="top"><span class="tile-icon commitment-icon">💳</span><span class="grow"><span class="name">${esc(d.name)}</span><span class="deadline ${days<0&&f.remaining?'text-danger':''}">${f.settled?'✓ Quitado':d.due?`Vence ${dateText(d.due)}`:'Sem vencimento'}</span></span>${arrow()}</span><span class="balance-line"><strong>${money(f.remaining)}</strong><span>${f.settled?'a pagar':'falta separar'}</span></span><span class="progress-wrap"><span class="track" aria-hidden="true"><span style="width:${f.progress}%"></span></span><span class="bottom"><span>Pago ${money(f.paid)}</span><strong>Reservado ${money(f.reserved)}</strong></span></span>${f.ready?'<span class="debt-ready-note">✓ Valor reservado · toque para quitar</span>':!f.settled?`<span class="fine">${money(f.balance)} aguardam pagamento</span>`:''}</button>`;
}
function renderDebts(){
 const active=state.debts.filter(d=>!d.archived&&LL.debtBalance(state,d)>0),done=state.debts.filter(d=>!d.archived&&!LL.debtBalance(state,d)),s=LL.summary(state);
 const missing=active.reduce((n,d)=>n+LL.cents(LL.debtFunding(state,d).remaining),0)/100;
 return head('Seus compromissos.','',btn(icon('plus'),'new-debt','','secondary compact','aria-label="Criar compromisso"'))+`<div class="balance-strip"><div><span class="label">Falta reservar</span><div class="amount">${money(missing)}</div><span class="fine">${money(s.debts)} ainda a pagar</span></div><span class="badge ${active.length?'rose':'green'}">${active.length?`${active.length} em aberto`:'Em dia'}</span></div><div class="pocket-grid">${active.length?active.map(debtCard).join(''):emptyBox('🌿','Nenhum compromisso em aberto.','Um espaço mais leve por aqui.','new-debt','Adicionar compromisso')}</div>${done.length?`<details class="quiet-details"><summary>Quitados · ${done.length}</summary><div class="pocket-grid">${done.map(debtCard).join('')}</div></details>`:''}`;
}
const appVersion=()=>globalThis.LLPlatform?.version||'25';
const platformLabel=()=>({ios:'iPhone',android:'Android'})[globalThis.LLPlatform?.platform]||'individual';
function settingsRow(ic,name,value,action){return `<button class="row-card" data-action="${action}"><span class="tile-icon">${icon(ic)}</span><span class="grow"><span class="name">${name}</span><small>${value}</small></span>${arrow()}</button>`;}
function renderSettings(){
 const dataRow=accessMode==='cloud'?settingsRow('shield','Conta e sincronização',esc(cloudUser?.email||'Conta Google'),'cloud-account'):accessMode==='guest'?settingsRow('eye','Modo conhecer','Dados temporários desta visita','guest-info'):settingsRow('shield','Backup e seus dados','Guardar uma cópia · restaurar','backup');
 const lockValue=accessMode==='cloud'?'Voltar para a tela de acesso':accessMode==='guest'?'Encerrar esta demonstração':'Pedir minha senha novamente';
 const note=accessMode==='cloud'?'Seus registros são sincronizados com sua conta e mantêm uma cópia criptografada neste aparelho.':accessMode==='guest'?'Nada deste modo é enviado ou guardado quando você sair.':'Seus registros ficam neste navegador, protegidos pela sua senha.';
 return head('Seu espaço.','Configurações')+`<div class="settings-list">${settingsRow('spark','Seu nome',esc(state.profile.name||'Como quer ser chamada?'),'profile')}${settingsRow('coins','Moeda',`${LL.CURRENCIES[state.preferences.currency][1]} · ${LL.CURRENCIES[state.preferences.currency][0]}`,'currency')}${settingsRow('calendar','Virar o mês',monthText(LL.planningMonth(state))+' · saldos preservados','month-rollover')}${settingsRow('refresh','Recomeçar planejamento','Só os planos, não o seu dinheiro','planning-reset')}${dataRow}${globalThis.LLPlatform?.native?'':settingsRow('phone','Instalar no celular','Seu app na tela inicial','install')}${settingsRow('archive','Arquivados','Histórico preservado','archives')}${settingsRow('info','Como funciona','Divisão, cofrinhos e privacidade','help')}${settingsRow('lock','Bloquear agora',lockValue,'lock')}${swWaiting?settingsRow('refresh','Atualização disponível','Seus dados serão preservados','update'):''}</div><p class="settings-note">${icon('shield')} ${note}</p><div class="version-note">Life Lately · versão ${esc(appVersion())} · ${esc(platformLabel())}</div>`;
}
function splitRows(shares,{totalLabel='Separado',emptyText='Defina seus cofrinhos em Organizar.',showTotal=true}={}){
 const entries=Object.entries(shares||{}).filter(([,v])=>v>0),total=entries.reduce((a,[,v])=>a+v,0);
 if(!entries.length)return `<div class="split-box"><p class="fine">${emptyText}</p></div>`;
 return `<div class="split-box"><div class="split-head"><span>Destino</span><span>Valor</span></div>${entries.map(([id,value])=>{const c=LL.cat(state,id);return `<div class="split-row" style="--category:${c?.color||'#d5839b'}"><span class="dot"></span><span class="grow">${esc(c?.label||'Cofrinho anterior')}</span><b>${money(value/100)}</b></div>`;}).join('')}${showTotal?`<div class="split-total"><span>${totalLabel}</span><span>${money(total/100)}</span></div>`:''}</div>`;
}
function openIncome(id=''){
 const t=state.transactions.find(t=>t.id===id),isNew=!t;
 modal(t?'Seu ganho':'Ganhei',`<form id="incomeForm">${moneyField('amount','Quanto entrou?',t?.value??'',true,'required')}${field('description','De onde veio? <span class="optional">opcional</span>',t?.description||'','text','maxlength="70" placeholder="Diária, comissão, trabalho…"')}${isNew?'<label class="checkbox-row"><span>Separar nos cofrinhos</span><input type="checkbox" name="distribute" checked aria-label="Separar nos cofrinhos"></label>':''}<div id="incomeSplitPreview"></div>${optionalDetails(`<div class="field-pair">${field('date','Recebi em',t?.date||LL.today(),'date',`required max="${LL.today()}"`)}<div class="field"><label for="incomeType">Tipo</label><select name="type" id="incomeType">${['Outro','Diária','Comissão','Job / freela','Venda','Serviço'].map(type=>`<option ${t?.type===type?'selected':''}>${type}</option>`).join('')}</select></div></div>`,'Data e tipo')}${!isNew?`<div class="list-divider">${btn('Excluir este ganho','income-delete',id,'action-muted text-danger')}</div>`:''}${footer(isNew?'Registrar ganho':'Salvar alteração')}</form>`,{focus:isNew?'[name=amount]':null});
 const update=()=>{try{const form=$('incomeForm'),amount=getAmount(form,'amount'),distribute=form.elements.distribute?.checked;if(isNew){const p=distribute?LL.allocation(state,amount):{shares:{},pending:LL.cents(amount)};$('incomeSplitPreview').innerHTML=amount?splitRows(p.shares,{emptyText:p.error||'Fica a separar em Organizar.'})+(p.overflowCents?`<p class="fine text-green">${money(p.overflowCents/100)} de excedente ficam em Livre.</p>`:'')+(p.pending&&Object.values(p.shares).some(Boolean)?`<p class="fine">${money(p.pending/100)} ficam a separar.</p>`:''):'';}else{$('incomeSplitPreview').innerHTML=Object.keys(t.allocationSnapshot).length?`<p class="fine">A divisão anterior fica preservada. Acréscimos respeitam os limites; a sobra vai para Livre.</p>`:'<p class="fine">Este ganho ainda não foi separado.</p>';}}catch{$('incomeSplitPreview').innerHTML='';}};
 $('incomeForm').addEventListener('input',update);$('incomeForm').addEventListener('change',update);update();
 bindForm('incomeForm',async form=>{const data=new FormData(form),value=getAmount(form,'amount');await commit(s=>LL.income(s,{id,value,description:data.get('description'),type:data.get('type'),date:data.get('date'),distribute:data.get('distribute')==='on'}),{after:result=>{if(isNew){if(result.pending===LL.cents(result.entry.value)){page='organize';render();toast('Ganho salvo. Agora escolha onde separar.');}else showReceipt('Ganho registrado',result.entry.value,result.shares);}else toast('Ganho e cofrinhos atualizados.');}});});
}
function showReceipt(title,value,shares){modal(title,`<div class="receipt"><div class="receipt-mark">${icon('check')}</div><h3>Dinheiro com destino.</h3><div class="amount">${money(value)}</div>${splitRows(shares)}</div>${btn('Pronto','close','','primary full')}`);}
function openApply(){
 let p;try{p=LL.previewPending(state);}catch(e){modal('Sua divisão precisa de um ajuste.',`<p class="form-note">${esc(e.message)}</p>${btn('Ajustar divisão','allocation','','primary full')}`);return;}
 if(!LL.pendingCents(state)){toast('Todos os ganhos já estão separados.');return;}
 if(!p.amountCents){modal('Para onde vai esse dinheiro?',`<div class="dialog-summary"><div class="tile-icon">✨</div><div><span class="label">A separar</span><div class="amount">${money(LL.pendingCents(state)/100)}</div></div></div><p class="form-note">Crie um cofrinho com o valor que precisa juntar.</p>${btn('Criar cofrinho','new-pocket','','primary full')}<div class="list-divider">${btn('Ou escolher porcentagens','allocation','','link-button')}</div>`);return;}
 modal('Separar nos cofrinhos',`<form id="applyForm"><div class="dialog-summary"><span class="tile-icon" style="background:var(--yellow-soft)">✨</span><div><span class="label">Pronto para separar</span><div class="amount">${money(p.amountCents/100)}</div></div></div>${splitRows(p.shares)}${p.remaining>0?`<p class="fine">${money(p.remaining/100)} continuam sem destino.</p>`:''}<p class="fine">Registra a separação no app. Não movimenta sua conta bancária.</p>${footer('Confirmar separação')}</form>`);
 bindForm('applyForm',async()=>{await commit(s=>LL.applyPending(s),{after:r=>showReceipt('Tudo separado',r.amountCents/100,r.shares)});});
}
const pocketEmojis=['🏠','💡','🛒','🚗','🎯','✈️','🌱','🐷','✨','❤️','🎓','🧾'];
const pocketColors=['#d5839b','#d9b65f','#78a58c','#81a7b5','#b295a2','#bb9170'];
function inferredIcon(label,fallback){const t=label.toLocaleLowerCase('pt-BR');return /luz|energia/.test(t)?'💡':/aluguel|casa|moradia/.test(t)?'🏠':/mercado|comida|alimenta/.test(t)?'🛒':/reserva|emergência|emergencia/.test(t)?'🌱':/viagem|férias|ferias/.test(t)?'✈️':/carro|transporte|gasolina/.test(t)?'🚗':fallback;}
function pocketForm(id='',role='custom',back=null){
 const c=LL.cat(state,id),isNew=!c;if(c?.role==='debt'&&LL.linkedDebts(state,id).length){openPocket(id,'plan');return;}
 let currentIcon=c?.icon||(role==='goal'?'🎯':'🏠'),currentColor=c?.color||pocketColors[0];
 const showRole=c?.role==='free'?'free':role==='goal'||c?.role==='goal'?'goal':'custom';
 modal(isNew?showRole==='goal'?'Uma nova meta':'Novo cofrinho':c.label,`<form id="pocketForm">${isNew&&showRole==='custom'?`<div class="chip-row" style="margin-bottom:19px">${['Aluguel','Luz','Mercado','Reserva'].map((name,i)=>btn(name,'pocket-template',name,'chip',`data-emoji="${['🏠','💡','🛒','🌱'][i]}"`)).join('')}</div>`:''}${field('label',showRole==='goal'?'O que você quer realizar?':'Nome',c?.label.replace(/^Meta · /,'')||'','text','required maxlength="60" placeholder="Ex.: Aluguel"')}${showRole!=='free'?moneyField('target','Quanto precisa juntar?',c?.targetAmount||'',false,isNew?'required':''):''}${showRole!=='free'?field('targetDate','Até quando? <span class="optional">opcional</span>',c?.targetDate||'','date'):''}${showRole!=='free'?`<div class="chip-row" style="margin-top:-5px;margin-bottom:20px">${[[1,'+1 mês'],[12,'+1 ano'],[120,'+10 anos'],[360,'+30 anos']].map(([m,l])=>btn(l,'date-shortcut',String(m),'chip','data-field="targetDate"')).join('')}</div>`:''}${showRole==='custom'?`<label class="checkbox-row repeat-setting"><span><b>Repetir todo mês</b><small class="fine">Renovar o prazo ao virar o mês.</small></span><input name="repeatMonthly" type="checkbox" ${c?.recurrence==='monthly'?'checked':''} aria-label="Repetir todo mês"></label>`:''}${optionalDetails(`<div class="field"><label>Ícone</label><div class="choice-grid" id="emojiChoices">${pocketEmojis.map(e=>btn(e,'pick-emoji',e,` ${e===currentIcon?'active':''}`,'aria-label="Escolher '+esc(e)+'"')).join('')}</div></div><div class="field name-color-field"><label>Cor</label><div class="palette">${pocketColors.map(color=>btn('','pick-color',color,`${color===currentColor?'selected-color':''}`,`style="--category:${color}" aria-label="Cor ${color}"`)).join('')}</div></div>`,'Personalizar')}${!isNew&&showRole!=='free'?`<div class="list-divider">${btn('Arquivar cofrinho','pocket-archive',id,'action-muted text-danger')}</div>`:''}${footer(isNew?'Criar '+(showRole==='goal'?'meta':'cofrinho'):'Salvar plano')}</form>`,{back:back||(!isNew?()=>openPocket(id):null),focus:isNew?'[name=label]':null});
 $('pocketForm').dataset.icon=currentIcon;$('pocketForm').dataset.color=currentColor;
 bindForm('pocketForm',async form=>{const data=new FormData(form),target=showRole==='free'?0:getAmount(form,'target');if(isNew&&showRole!=='free'&&!target)throw Error('Informe quanto precisa juntar.');await commit(s=>LL.upsertPocket(s,{id,label:data.get('label'),targetAmount:target,targetDate:data.get('targetDate')||'',recurrence:showRole==='custom'&&data.has('repeatMonthly')?'monthly':'once',role:showRole,icon:isNew&&!form.dataset.iconPicked?inferredIcon(data.get('label'),form.dataset.icon):form.dataset.icon,color:form.dataset.color}),{after:saved=>{page=showRole==='goal'?'goals':'organize';render();toast(isNew?'Cofrinho criado. Os próximos ganhos já entram no plano.':'Plano atualizado. O dinheiro já separado não muda.');}});});
}
function pocketHistory(c){return (state.activity||[]).filter(a=>a.targetId===c.id||c.goalId&&a.targetId===c.goalId);}
function openPocket(id,tab='summary'){
 const c=LL.cat(state,id);if(!c)return;const t=LL.target(state,c),stats=LL.pocketStats(state,id),links=LL.linkedDebts(state,id);
 if(c.closedForDebt){tab='history';}
 if(tab==='plan'&&!links.length){pocketForm(id,c.role,()=>openPocket(id));return;}
 const tabs=`<div class="tabs" aria-label="Detalhes do cofrinho">${(c.closedForDebt?[['history','Histórico']]:[['summary','Cofrinho'],['plan','Plano'],['history','Histórico']]).map(([key,label])=>btn(label,'pocket-tab',id,tab===key?'active':'',`data-tab="${key}" aria-pressed="${tab===key}"`)).join('')}</div>`;
 let body='';
 if(tab==='history'){const entries=state.transactions.filter(t=>LL.contributionCents(t,id)>0).sort((a,b)=>b.date.localeCompare(a.date));body=entries.length?`<h3>Vindo dos ganhos</h3><div class="list" style="margin:12px 0 24px">${entries.slice(0,80).map(t=>`<button class="row-card" data-action="income-open" data-id="${esc(t.id)}"><span class="grow"><span class="name">${esc(t.description)}</span><small>${dateText(t.date)}</small></span><strong class="text-green">+ ${money(LL.contributionCents(t,id)/100)}</strong>${arrow()}</button>`).join('')}</div>`:'';body+=`<h3 style="margin-bottom:12px">Movimentações</h3>${activityList(pocketHistory(c),80)}`;}

 else if(tab==='plan'&&links.length)body=`${c.planningPaused?`<div class="alert-inline">O compromisso continua registrado. Só a separação automática está pausada.</div>${btn('Retomar no planejamento','planning-resume',id,'secondary full')}`:''}<p class="form-note">O valor e o prazo vêm dos compromissos abaixo.</p><div class="list">${links.map(d=>`<button class="row-card" data-action="debt-open" data-id="${esc(d.id)}"><span class="tile-icon commitment-icon">💳</span><span class="grow"><b>${esc(d.name)}</b><small>${dateText(d.due)}</small></span><strong>${money(LL.debtBalance(state,d))}</strong>${arrow()}</button>`).join('')}</div>`;
 else body=`${stats.balance<0?'<div class="alert-inline">Este saldo já estava negativo. Corrija ou reponha o valor para regularizar.</div>':''}${t.amount?`<div class="target-recap"><div class="between"><div><span class="label">Quero ter</span><div><b>${money(t.amount)}</b></div></div><span class="badge ${t.done?'green':t.days<0?'danger':'rose'}">${esc(deadline(t))}</span></div><span class="track" style="--category:${c.color}"><span style="width:${Math.min(100,Math.max(0,t.covered/t.amount*100))}%"></span></span><div class="recap-footer"><span>${t.done?(t.used>0?'Atendido neste ciclo':'Valor completo'):`Faltam ${money(t.remaining)}`}</span><span>${t.date?dateText(t.date,true):'Sem prazo'}</span></div></div>`:c.planningPaused?`<p class="fine">Seu saldo está guardado. Defina o próximo plano quando quiser.</p>${btn('Replanejar este cofrinho','pocket-tab',id,'secondary full','data-tab="plan"')}`:'<p class="fine">Um espaço para o dinheiro sem outro destino.</p>'}${t.used>0?`<p class="fine" style="margin-top:12px">${money(t.used)} já usados neste ciclo. ${t.done?'Não precisa separar de novo.':''}</p>`:''}<div class="detail-metrics"><div><small>Separado dos ganhos</small><b>${money(stats.allocated)}</b></div><div><small>Total usado</small><b>${money(stats.spent)}</b></div></div>${stats.added||stats.adjustments||stats.transferred?`<p class="fine">De fora: ${money(stats.added)} · transferências: ${money(stats.transferred)} · ajustes: ${money(stats.adjustments)}</p>`:''}${t.amount&&t.remaining>0&&t.days!==null?`<p class="fine" style="margin-top:14px">Faltam, em média, ${money(t.remaining/Math.max(1,t.days))} por dia para o prazo.</p>`:''}<div class="dialog-foot stack">${c.role==='free'&&stats.balance>0?btn(icon('spark')+' Distribuir Livre','free-distribute',id,'primary full'):''}${links.length&&t.done?btn('Confirmar em Compromissos','debt-open',links.find(d=>LL.debtBalance(state,d)>0)?.id||links[0].id,'primary full'):''}${btn(icon('transfer')+' Movimentar','pocket-move',id,(c.role==='free'&&stats.balance>0||links.length&&t.done)?'secondary full':'primary full')}</div>`;
 modal(c.label.replace(/^Meta · /,''),`<div class="dialog-summary"><span class="tile-icon" style="background:${c.color}22">${esc(c.icon)}</span><div><span class="label">No cofrinho</span><div class="amount">${money(stats.balance)}</div></div></div>${tabs}${body}`);
}
function openMove(id,selected=''){
 const c=LL.cat(state,id);if(!c)return;const links=LL.linkedDebts(state,id).filter(d=>LL.debtBalance(state,d)>0),allLinks=LL.linkedDebts(state,id),actions=[...(allLinks.length?(links.length?[['payment','Paguei um compromisso']]:[]):[['spend','Usei deste cofrinho']]),['transfer','Transferir entre cofrinhos'],['deposit','Coloquei dinheiro de fora'],['adjustment','Corrigir saldo']];
 let action=selected||actions[0][0];if(!actions.some(a=>a[0]===action))action=actions[0][0];
 const balance=LL.pocket(state,id),others=LL.cats(state).filter(x=>x.id!==id);
 const hint={spend:'Seus ganhos continuam iguais. Só este cofrinho diminui.',transfer:'Sai daqui e entra no outro. Não conta como gasto.',deposit:'Dinheiro que já estava fora do app. Não registre de novo em Ganhos.',adjustment:'Registre quanto existe de verdade neste cofrinho.',payment:'O pagamento reduz o compromisso e usa a reserva deste cofrinho.'}[action];
 modal(c.label,`<form id="moveForm"><div class="field"><label for="moveType">O que aconteceu?</label><select id="moveType" name="action">${actions.map(([key,label])=>`<option value="${key}" ${key===action?'selected':''}>${label}</option>`).join('')}</select></div>${action==='payment'?`<div class="field"><label for="moveDebt">Compromisso</label><select name="debtId" id="moveDebt">${links.map(d=>`<option value="${esc(d.id)}">${esc(d.name)} · ${money(LL.debtBalance(state,d))}</option>`).join('')}</select></div>`:''}${moneyField('amount',action==='adjustment'?'Quanto tem agora?':action==='payment'?'Quanto pagou?':'Qual valor?',action==='adjustment'?Math.max(0,balance):'',true,'required')}${action==='transfer'?`<div class="field"><label for="moveDestination">Para qual cofrinho?</label><select name="destinationId" id="moveDestination" required><option value="">Escolha</option>${others.map(x=>`<option value="${x.id}">${esc(x.label)} · ${money(LL.pocket(state,x.id))}</option>`).join('')}</select></div>`:''}<div id="movePreview"></div><p class="form-note">${hint}</p>${optionalDetails(`<div class="field-pair">${field('date','Quando?',LL.today(),'date',`required max="${LL.today()}"`)}${field('note','Observação','','text','maxlength="120" placeholder="Opcional"')}</div>`,'Data e observação')}${footer(action==='payment'?'Registrar pagamento':action==='transfer'?'Confirmar transferência':action==='adjustment'?'Corrigir saldo':'Registrar')}</form>`,{back:()=>openPocket(id)});

 const update=()=>{try{
  const form=$('moveForm'),n=getAmount(form,'amount');
  if(action==='payment'){
   const f=LL.debtFunding(state,form.elements.debtId.value),available=Math.max(0,balance);
   $('movePreview').innerHTML=beforeAfter(balance,Math.max(0,balance-n),'No cofrinho','Depois')+(n>available?`<p class="fine">${money(n-available)} pagos fora dos cofrinhos.</p>`:'');
  }else{
   const p=LL.previewMove(state,id,action,n,{destinationId:form.elements.destinationId?.value});
   $('movePreview').innerHTML=beforeAfter(p.before,p.after,'No cofrinho','Depois')+(p.shares?splitRows(p.shares,{totalLabel:action==='deposit'?'Aporte':'Destino'}):'')+(p.overflowCents?`<p class="fine text-green">O limite foi respeitado. ${money(p.overflowCents/100)} ${c.role==='free'?'continuam em Livre':'vão para Livre'}.</p>`:'');
  }
 }catch(e){$('movePreview').innerHTML=`<p class="fine">${esc(e.message)}</p>`;}};
 $('moveType').addEventListener('change',e=>openMove(id,e.target.value));$('moveForm').addEventListener('input',update);update();
 bindForm('moveForm',async form=>{const f=new FormData(form),amount=getAmount(form,'amount'),options={date:f.get('date'),note:f.get('note'),destinationId:f.get('destinationId')};await commit(s=>action==='payment'?LL.payDebt(s,f.get('debtId'),amount,{...options,sourceId:id}):LL.move(s,id,action,amount,options),{after:()=>{if(action==='payment')showPage('debts');else openPocket(id);toast('Movimentação registrada.');}});});
}
function beforeAfter(before,after,labelBefore='Antes',labelAfter='Depois'){return `<div class="two-values"><div><small>${labelBefore}</small><b>${money(before)}</b></div>${icon('arrow')}<div><small>${labelAfter}</small><b>${money(after)}</b></div></div>`;}
function newDebt(){debtForm();}
function debtForm(id='',back=null){const d=state.debts.find(d=>d.id===id),balance=d?LL.debtBalance(state,d):'';
 modal(d?d.name:'Novo compromisso',`<form id="debtForm">${field('name','Nome',d?.name||'','text','required maxlength="60" placeholder="Ex.: Cartão"')}${moneyField('total',d?'Quanto ainda falta pagar?':'Quanto precisa pagar?',balance,true,'required')}${field('due','Vence em <span class="optional">opcional</span>',d?.due||'','date')}<p class="fine">${d?'Mudar o valor registra uma correção de saldo.':'Um cofrinho para esse compromisso será criado em Organizar.'}</p>${d?`<div class="list-divider">${btn('Arquivar compromisso','debt-archive',id,'action-muted text-danger')}</div>`:''}${footer(d?'Salvar alteração':'Criar compromisso e cofrinho')}</form>`,{back:back||(d?()=>openDebt(id):null),focus:d?null:'[name=name]'});
 bindForm('debtForm',async form=>{const f=new FormData(form),total=getAmount(form,'total');await commit(s=>LL.upsertDebt(s,{id,name:f.get('name'),total,due:f.get('due')}),{after:()=>{page='debts';render();toast(d?'Compromisso e plano atualizados.':'Compromisso criado. Seu cofrinho está em Organizar.');}});});
}

function openDebt(id,tab='pay'){
 const d=state.debts.find(d=>d.id===id);if(!d)return;
 if(tab==='data'){debtForm(id);return;}
 const f=LL.debtFunding(state,d),c=LL.cat(state,d.pocketId),remaining=f.balance;
 const top=`<div class="dialog-summary"><span class="tile-icon commitment-icon">💳</span><div><span class="label">${f.settled?'Quitado':'Falta reservar'}</span><div class="amount">${money(f.remaining)}</div></div></div><div class="tabs">${[['pay','Resumo'],['data','Dados'],['history','Histórico']].map(([key,label])=>btn(label,'debt-tab',id,tab===key?'active':'',`data-tab="${key}" aria-pressed="${tab===key}"`)).join('')}</div>`;
 let body='';
 if(tab==='history')body=activityList(state.activity.filter(a=>a.targetType==='debt'&&a.targetId===id),80);
 else if(f.settled)body=`<div class="success-note">✓ Quitado. ${money(f.paid)} pagos.</div>${c&&!c.archived&&!LL.linkedDebts(state,c.id).some(x=>LL.debtBalance(state,x)>0)?`<div class="list-divider">${btn('Concluir cofrinho','debt-settle',id,'primary full')}</div>`:''}${c?`<div class="list-divider">${btn('Ver histórico do cofrinho','pocket-tab',c.id,'secondary full','data-tab="history"')}</div>`:''}`;
 else if(tab!=='partial')body=`<div class="debt-funding-panel ${f.ready?'ready':''}"><span class="badge ${f.ready?'green':'rose'}">${f.ready?'✓ Pronta para quitar':'Juntando para pagar'}</span><div class="funding-breakdown"><div><small>A pagar</small><b>${money(f.balance)}</b></div><span>−</span><div><small>Já reservado</small><b>${money(f.reserved)}</b></div></div><span class="track" style="--category:#78a58c"><span style="width:${f.progress}%"></span></span><p class="fine">${f.ready?'Não recebe mais aportes. Confirme quando pagar.':'Cada valor separado em Organizar reduz o que falta reservar.'}</p></div><div class="detail-metrics"><div><small>Já pago</small><b>${money(f.paid)}</b></div><div><small>Vencimento</small><b class="date-metric">${d.due?dateText(d.due,true):'Sem prazo'}</b></div></div>${c&&!c.archived?btn('Ver cofrinho '+icon('arrow'),'pocket',c.id,'link-button'):''}<div class="dialog-foot stack">${btn(icon('check')+' Quitei','debt-settle',id,'primary full')}${btn('Paguei uma parte','debt-tab',id,'secondary full','data-tab="partial"')}</div>`;
 else body=`<form id="payForm">${moneyField('amount','Quanto pagou?','',true,'required')}<div class="field"><label for="paySource">De onde saiu?</label><select id="paySource" name="sourceId">${LL.cats(state).map(x=>`<option value="${x.id}" ${x.id===d.pocketId?'selected':''}>${esc(x.label)} · ${money(LL.pocket(state,x.id))}</option>`).join('')}<option value="">Dinheiro fora dos cofrinhos</option></select></div><div id="payPreview"></div>${optionalDetails(`<div class="field-pair">${field('date','Paguei em',LL.today(),'date',`required max="${LL.today()}"`)}${field('note','Observação','','text','maxlength="120" placeholder="Opcional"')}</div>`,'Data e observação')}${footer('Registrar pagamento')}</form>`;
 modal(d.name,top+body,tab==='partial'?{back:()=>openDebt(id)}:{});
 if($('payForm')){const update=()=>{try{const n=getAmount($('payForm'),'amount'),source=$('paySource').value,available=Math.max(0,LL.pocket(state,source)),funded=Math.min(n,available);$('payPreview').innerHTML=beforeAfter(remaining,Math.max(0,remaining-n),'A pagar agora','Depois de pagar')+`<p class="fine">${source?`${money(funded)} do cofrinho${n>funded?` + ${money(n-funded)} de fora`:''}.`:`${money(n)} pagos fora dos cofrinhos.`}</p>`;}catch{$('payPreview').innerHTML='';}};$('payForm').addEventListener('input',update);$('payForm').addEventListener('change',update);update();bindForm('payForm',async form=>{const f=new FormData(form);await commit(s=>LL.payDebt(s,id,getAmount(form,'amount'),{date:f.get('date'),note:f.get('note'),sourceId:f.get('sourceId')}),{after:()=>{showPage('debts');toast(LL.debtBalance(state,id)===0?'Compromisso quitado. Cofrinho concluído.':'Pagamento e cofrinho atualizados.');}});});}
}
function openSettlement(id){
 const d=state.debts.find(x=>x.id===id);if(!d)return;
 let preview=LL.settlementPreview(state,id);
 modal('Confirmar quitação',`<form id="settleForm"><div class="dialog-summary"><span class="tile-icon commitment-icon">💳</span><div><span class="label">${esc(d.name)}</span><div class="amount">${money(preview.balance)}</div></div></div>${preview.amountCents?`<div class="field"><label for="settleSource">De onde saiu?</label><select id="settleSource" name="sourceId">${LL.cats(state).map(c=>`<option value="${esc(c.id)}" ${c.id===d.pocketId?'selected':''}>${esc(c.label)} · ${money(LL.pocket(state,c.id))}</option>`).join('')}<option value="">Dinheiro fora dos cofrinhos</option></select></div>`:''}<div id="settleBreakdown"></div>${field('date','Paguei em',LL.today(),'date',`required max="${LL.today()}"`)}<label class="check-normal"><input name="confirmPaid" type="checkbox" required><span id="settleConfirmation">Já fiz esse pagamento.</span></label><p class="fine">${LL.linkedDebts(state,d.pocketId).some(x=>x.id!==id&&LL.debtBalance(state,x)>0)?'Este compromisso fica em Quitados. O cofrinho continua para os outros compromissos vinculados.':'O cofrinho sai de Organizar. O histórico fica em Compromissos → Quitados.'}</p>${footer('Confirmar: quitei')}</form>`,{back:()=>openDebt(id)});
 const update=()=>{preview=LL.settlementPreview(state,id,$('settleSource')?.value);$('settleBreakdown').innerHTML=`<div class="settlement-recap"><div><span>Da reserva</span><b>${money(preview.fundedCents/100)}</b></div>${preview.externalCents?`<div class="text-rose"><span>De fora do cofrinho</span><b>${money(preview.externalCents/100)}</b></div>`:''}<div><span>Após quitar</span><b>${money(0)} a pagar</b></div></div>`;$('settleConfirmation').textContent=preview.externalCents?`Já paguei ${money(preview.balance)}, incluindo ${money(preview.externalCents/100)} fora desta reserva.`:'Já fiz esse pagamento.';$('settleForm').elements.confirmPaid.checked=false;};
 $('settleSource')?.addEventListener('change',update);update();
 bindForm('settleForm',async form=>{if(!form.elements.confirmPaid.checked)throw Error('Confirme o pagamento realizado.');await commit(s=>LL.settleDebt(s,id,{sourceId:preview.sourceId,date:form.elements.date.value,allowExternal:true,expectedSignature:preview.signature}),{after:()=>{showPage('debts');toast('Quitado. Seu histórico continua guardado.');}});});
}
function openFreeDistribution(id=''){
 const c=id?LL.cat(state,id):LL.cats(state).find(c=>c.role==='free');
 if(!c||LL.pocket(state,c.id)<=0){toast('Ainda não há saldo Livre para distribuir.');return;}
 const available=Math.max(0,LL.pocket(state,c.id));let preview=null;
 modal('Distribuir Livre',`<form id="freeForm"><div class="free-context"><span class="tile-icon">✨</span><div><span class="label">Saldo que já é seu</span><b>${money(available)}</b><small>Não conta como novo ganho.</small></div></div>${moneyField('amount','Quanto quer aproveitar?',available,true,'required')}<div id="freePreview" aria-live="polite"></div><p class="fine">Só o que falta vai para os cofrinhos. O restante continua Livre.</p>${footer('Confirmar distribuição')}</form>`,{back:()=>openPocket(c.id)});
 const update=()=>{const submit=$('freeForm').querySelector('[type=submit]');try{preview=LL.previewFree(state,getAmount($('freeForm'),'amount'),{sourceId:c.id});$('freePreview').innerHTML=splitRows(preview.shares,{totalLabel:'Vai para os planos',emptyText:'Nenhum plano precisa receber agora.'})+beforeAfter(available,preview.remainingFreeCents/100,'Livre agora','Continua Livre');submit.disabled=!preview.movedCents;}catch(e){preview=null;$('freePreview').innerHTML=`<div class="alert-inline">${esc(e.message)}</div>`;submit.disabled=true;}};
 $('freeForm').addEventListener('input',update);update();
 bindForm('freeForm',async form=>{if(!preview?.movedCents)throw Error('Não há valor para distribuir.');const signature=preview.signature;await commit(s=>LL.distributeFree(s,getAmount(form,'amount'),{sourceId:c.id,expectedSignature:signature}),{after:r=>{page='organize';render();modal('Livre redistribuído',`<div class="receipt"><div class="receipt-mark">${icon('check')}</div><h3>Seu saldo ganhou novos destinos.</h3></div>${splitRows(r.shares,{totalLabel:'Distribuído'})}<div class="success-note">${money(r.remainingFreeCents/100)} continuam Livre.</div><p class="fine" style="margin:15px 0">Seu total de ganhos não mudou.</p>${btn('Pronto','close','','primary full')}`);}});});
}
function openIncomeTarget(key){const monthly=key==='monthly';modal(monthly?'Quanto quero ganhar no mês':'Quanto quero ganhar na semana',`<form id="incomeTargetForm">${moneyField('target',monthly?'Meta de renda mensal':'Meta de renda semanal',state.goals[key]||'',true)}<p class="form-note">É uma referência de renda, não dinheiro já recebido.</p>${footer('Salvar referência')}</form>`);bindForm('incomeTargetForm',async form=>{const value=getAmount(form,'target');await commit(s=>{LL.recordActivity(s,'goal',key,monthly?'Meta de renda mensal':'Meta de renda semanal',s.goals[key],value,'','configure');s.goals[key]=value;},{message:'Referência de renda salva.'});});}
let allocationDraft=null;
function openAllocation(mode=state.preferences.allocationMode){
 const preview=LL.allocation(state,100),actual=LL.cats(state);
 if(!allocationDraft)allocationDraft=Object.fromEntries(actual.map(c=>[c.id,state.preferences.allocationMode==='manual'?Number(state.allocation[c.id]||0):(preview.shares[c.id]||0)/100]));
 if(!Object.values(allocationDraft).some(Boolean)){const f=actual.find(c=>c.role==='free');if(f)allocationDraft[f.id]=100;}
 const f=LL.forecast(state),projections=mode==='auto'?splitRows(LL.allocation(state,100,LL.today(),'auto').shares,{totalLabel:'A cada '+compactMoney(100),emptyText:'Crie cofrinhos com valor e prazo para o app dividir.'}):'';
 modal('Como separar',`<div class="tabs">${btn(icon('spark')+' Automático','allocation-mode','auto',mode==='auto'?'active':'',`aria-pressed="${mode==='auto'}"`)}${btn('Escolher %','allocation-mode','manual',mode==='manual'?'active':'',`aria-pressed="${mode==='manual'}"`)}</div><form id="allocationForm">${mode==='auto'?`<p class="form-note">Você diz o valor e o prazo. O app divide cada ganho pelo que ainda falta juntar.</p>${projections}${f.hasTargets?`<div class="target-recap"><span class="label">Ritmo necessário para todos os planos</span><div class="amount sm">${money(f.daily)}<span class="label"> / dia</span></div><p class="fine" style="margin-top:6px">${f.expectedMonthly?`Renda informada: ${money(f.expectedMonthly)}/mês.`:'Sem previsão de renda: o prazo depende dos próximos ganhos.'}</p></div>`:''}${optionalDetails('<p>Quanto maior o valor que falta e menor o prazo, maior a parte do próximo ganho. Com o mesmo prazo, aluguel de 400, luz de 30 e compromisso de 40 recebem partes proporcionais a 400:30:40.</p><p>O saldo já guardado é descontado. Um cofrinho completo para de receber; o restante vai para Livre. Prazos vencidos continuam no plano com prioridade maior. Um alvo sem prazo usa 30 dias como referência de divisão, sem criar vencimento.</p><p>Essa divisão não garante renda futura nem rendimento. Os valores não consideram juros ou inflação.</p>','Entender a conta')}`:`<div id="manualTotal" class="manual-total"><div><small>Total da divisão</small><strong id="manualPct">100%</strong></div><small id="manualHint"></small></div><div>${actual.map(c=>`<div class="manual-row"><div class="between"><div class="flex"><span>${esc(c.icon)}</span><span><b>${esc(c.label)}</b>${LL.funding(state,c).done?'<small class="manual-complete">✓ Completo · parte vai para Livre</small>':''}</span></div><div class="percent-wrap"><input class="manual-numeric input-filter" type="number" min="0" max="100" step="0.01" data-pct-number="${c.id}" value="${allocationDraft[c.id]||0}" aria-label="Percentual de ${esc(c.label)}"><span class="fine">%</span></div></div><input type="range" min="0" max="100" step="0.01" value="${allocationDraft[c.id]||0}" data-slider="${c.id}" aria-label="Arrastar percentual de ${esc(c.label)}"></div>`).join('')}</div><p class="manual-warning">As barras continuam livres. Cofrinhos completos não recebem; a sobra vai para Livre.</p><div id="manualEffective"></div>`}${footer(mode==='auto'?'Usar divisão automática':'Salvar porcentagens')}</form>`);
 if(mode==='manual'){
  const update=()=>{const total=Object.values(allocationDraft).reduce((a,v)=>a+Number(v),0),ok=Math.abs(total-100)<.005;$('manualPct').textContent=pct(total);$('manualTotal').className=`manual-total ${ok?'ok':total>100?'over':''}`;$('manualHint').textContent=ok?'✓ Pronto para salvar':total<100?`Faltam ${pct(100-total)}`:`Passou ${pct(total-100)}`;$('allocationForm').querySelector('[type=submit]').disabled=!ok;const draft=LL.clone(state);draft.allocation={...draft.allocation,...allocationDraft};const p=LL.allocation(draft,100,LL.today(),'manual');$('manualEffective').innerHTML=ok?splitRows(p.shares,{totalLabel:'Destino real de '+compactMoney(100)})+(p.overflowCents?`<p class="fine text-green">${money(p.overflowCents/100)} excedentes → Livre.</p>`:''):'';};
  $('allocationForm').addEventListener('input',e=>{const el=e.target,id=el.dataset.slider||el.dataset.pctNumber;if(!id)return;const v=Math.max(0,Math.min(100,Number(el.value)||0));allocationDraft[id]=v;const counterpart=$('allocationForm').querySelector(el.dataset.slider?`[data-pct-number="${id}"]`:`[data-slider="${id}"]`);counterpart.value=v;update();});update();
 }
 bindForm('allocationForm',async()=>{await commit(s=>{if(mode==='manual')LL.setManual(s,allocationDraft);else{s.preferences.allocationMode='auto';s.preferences.autoConfigured=true;LL.recordActivity(s,'allocation','main','Divisão automática ativada',0,0,'','configure');}},{after:()=>{allocationDraft=null;toast('Divisão salva para os próximos ganhos.');}});});
}

// Period management is always explicit. Shared core previews keep money and plans separate.
const monthName=m=>new Date(m+'-01T12:00:00').toLocaleDateString('pt-BR',{month:'long'});
const monthText=(m,short=false)=>new Date(m+'-01T12:00:00').toLocaleDateString('pt-BR',{month:short?'short':'long',year:'numeric'});
function planningToolbar(){
 const period=LL.planningMonth(state),u=state.planning?.undo;
 return `<section class="planning-tools" aria-label="Ações do planejamento"><div class="planning-period"><span class="kicker">Seu planejamento</span><span>${esc(monthText(period))}</span></div><div class="planning-actions"><button type="button" data-action="month-rollover" class="planning-tool next-period"><span class="tool-symbol">${icon('calendar')}</span><span><b>Virar o mês</b><small>Levar meus saldos</small></span>${arrow()}</button><button type="button" data-action="planning-reset" class="planning-tool"><span class="tool-symbol">${icon('refresh')}</span><span><b>Recomeçar plano</b><small>Manter meu dinheiro</small></span>${arrow()}</button></div>${u&&LL.canUndoPlanning(state)?`<div class="planning-undo"><span>${icon('check')} ${u.kind==='reset'?'Planejamento reiniciado':'Mês virado'}</span>${btn('Desfazer','planning-undo',u.id,'link-button')}</div>`:''}</section>`;
}
function safeSummary(title,value,caption){return `<div class="plan-safe-summary"><span class="plan-safe-icon">${icon('shield')}</span><div class="grow"><span class="label">${title}</span><strong class="amount sm">${money(value)}</strong><p class="fine">${caption}</p></div></div>`;}
function managementFooter(label,primary='primary'){return `<div class="dialog-foot management-footer">${btn('Cancelar','close','','secondary')}<button type="submit" class="${primary}">${esc(label)}</button></div>`;}
function openPlanningReset(){
 const preview=LL.resetPlanPreview(state),signature=LL.planSignature(state);
 if(!preview.canReset){modal('Seu plano já está zerado',`${safeSummary('Guardado nos cofrinhos',preview.summary.pockets,'Nenhum saldo precisa ser apagado.')}<p class="form-note">Crie um cofrinho ou uma meta para começar.</p>${btn('Ir para Organizar','nav','organize','primary full')}`);return;}
 const details=preview.plans.map(c=>`<div class="plan-change-row"><span>${esc(c.icon||'🐷')}</span><span class="grow"><b>${esc(c.label)}</b><small>${c.role==='debt'?'Separação pausada; compromisso preservado':'Objetivo e prazo serão limpos'}</small></span><strong>${money(c.target)}</strong></div>`).join('');
 modal('Recomeçar planejamento',`<form id="planningResetForm">${safeSummary('Seu dinheiro continua aqui',preview.summary.pockets,'Saldos e movimentações ficam intactos.')}<div class="plan-impact"><div><span class="impact-check">${icon('check')}</span><p><b>Ficam</b><span>Seu acesso, cofrinhos, ganhos, compromissos e pagamentos.</span></p></div><div><span class="impact-reset">${icon('refresh')}</span><p><b>Recomeçam</b><span>Objetivos, prazos dos cofrinhos, percentuais e referências de renda.</span></p></div></div>${optionalDetails(details||'<p>Limpar a divisão e as referências de renda.</p>',`Ver ${preview.plans.length} plano(s) afetado(s)`)}<p class="fine" style="margin-top:15px">Compromissos não são pagos nem excluídos. A separação automática fica pausada até você planejar de novo.</p><label class="check-normal"><input name="confirmResetPlan" type="checkbox" required><span>Quero refazer só o planejamento.</span></label>${managementFooter('Recomeçar plano')}</form>`);
 bindForm('planningResetForm',async()=>{await commit(d=>LL.resetPlanning(d,{expectedSignature:signature}),{after:id=>{page='organize';allocationDraft=null;render();openPlanningResult('reset',id);}});});
}
function openMonthRollover(){
 const p=LL.rolloverPreview(state),signature=LL.planSignature(state);
 if(!p.canAdvance){modal('O próximo mês já está aberto',`${safeSummary('Seus cofrinhos continuam',LL.summary(state).pockets,`Planejamento de ${monthText(p.from)}.`)}<p class="form-note">A próxima virada fica disponível quando o calendário chegar a ${esc(monthName(p.from))}. Você ainda pode desfazer a última virada pelo histórico.</p>${btn('Ver histórico','planning-history','','secondary full')}`);return;}
 const rows=p.candidates.map(c=>`<label class="renewal-row"><input type="checkbox" name="renewPocket" value="${esc(c.id)}" ${c.monthly?'checked':''}><span class="renewal-icon">${esc(c.icon)}</span><span class="grow"><b>${esc(c.label)} <span class="badge ${c.monthly?'rose':''}">${c.monthly?'Todo mês':'Só esta vez'}</span></b><small>${dateText(c.fromDate,true)} → <strong>${dateText(c.toDate,true)}</strong></small><small>${money(c.amount)} de objetivo · ${money(c.balance)} guardados</small>${c.complete?'<small class="text-green">✓ Atendido neste ciclo</small>':''}</span></label>`).join('');
 modal('Virar o mês',`<form id="monthRolloverForm"><div class="month-transition"><div><span class="kicker">Encerrar</span><b>${esc(monthName(p.from))}</b><small>${p.from.slice(0,4)}</small></div><span class="month-arrow">${icon('arrow')}</span><div><span class="kicker">Começar</span><b>${esc(monthName(p.to))}</b><small>${p.to.slice(0,4)}</small></div></div><div class="detail-metrics period-metrics"><div><small>Entrou em ${monthName(p.from)}</small><b>${money(p.metrics.incomeCents/100)}</b></div><div><small>Continua nos cofrinhos</small><b>${money(p.metrics.pocketCents/100)}</b></div></div>${p.metrics.freeCents>0?`<div class="carry-free-note"><span>✨ Livre que continua</span><b>${money(p.metrics.freeCents/100)}</b><small>Você pode distribuir depois. Não é novo ganho.</small></div>`:''}${p.candidates.length?`<fieldset class="renewal-list"><legend>Renovar para ${monthName(p.to)}</legend><p class="fine">Só os marcados mudam de data.</p>${rows}</fieldset>`:'<p class="form-note">Nenhum compromisso para renovar. Seus planos continuam como estão.</p>'}<div class="preserve-note">${icon('shield')}<p>Metas de longo prazo, compromissos e saldos continuam. Nada é marcado como pago.</p></div>${p.metrics.pendingCents?`<p class="fine">${money(p.metrics.pendingCents/100)} a separar também seguem com você.</p>`:''}${p.early?'<p class="fine early-note">Você está adiantando o planejamento. Os ganhos continuam na data em que entraram.</p>':''}${managementFooter('Abrir '+monthName(p.to))}</form>`);
 bindForm('monthRolloverForm',async form=>{const renewIds=new FormData(form).getAll('renewPocket');await commit(d=>LL.rollMonth(d,{expectedMonth:p.from,expectedSignature:signature,renewIds}),{after:r=>{monthFilter=LL.planningMonth(state);page='organize';render();openPlanningResult('rollover',r.id);}});});
}
function openPlanningResult(kind,id){
 const isReset=kind==='reset',r=state.planning.closures.find(r=>r.id===id);
 modal(isReset?'Pronta para replanejar':`${monthName(LL.planningMonth(state))} está aberto`, `<div class="receipt plan-receipt"><div class="receipt-mark">${icon('check')}</div><h3>${isReset?'Novos planos. Mesma história.':'Um novo mês, sem perder nada.'}</h3><p class="fine">${isReset?'O dinheiro guardado e os pagamentos foram mantidos.':`${r?.renewed.length||0} plano(s) renovado(s). Seus saldos seguem com você.`}</p></div>${safeSummary('Nos seus cofrinhos',LL.summary(state).pockets,'Nenhum dinheiro foi adicionado ou retirado.')}<div class="stack">${!isReset&&LL.summary(state).free>0?btn('Distribuir saldo Livre','free-distribute','','primary full'):''}${btn('Ir para Organizar','nav','organize',!isReset&&LL.summary(state).free>0?'secondary full':'primary full')}${btn(isReset?'Desfazer reinício':'Desfazer virada','planning-undo',id,'secondary full')}${btn('Ver histórico','planning-history','','link-button')}</div>`);
}
function openPlanningUndo(id){
 const u=state.planning?.undo;
 if(!u||u.id!==id||!LL.canUndoPlanning(state)){modal('O plano já mudou',`<p class="form-note">Para não sobrescrever suas edições, esta ação não pode mais ser desfeita. O plano anterior continua no histórico.</p>${btn('Ver histórico','planning-history','','primary full')}`);return;}
 modal(u.kind==='reset'?'Desfazer reinício?':'Desfazer virada?',`<form id="planningUndoForm"><p class="form-note">Só o planejamento anterior será restaurado. Nenhum ganho, uso de cofrinho ou pagamento será desfeito.</p>${managementFooter('Restaurar planejamento')}</form>`);
 bindForm('planningUndoForm',async()=>{await commit(s=>LL.undoPlanning(s,id),{after:()=>{monthFilter=LL.planningMonth(state);render();toast('Planejamento restaurado. Seu dinheiro não mudou.');}});});
}
function planningRecords(){return [...(state.planning?.closures||[]),...(state.planning?.resets||[])].sort((a,b)=>b.createdAt.localeCompare(a.createdAt));}
function openPlanningHistory(){
 const rows=planningRecords();modal('Histórico do planejamento',rows.length?`<p class="form-note">Um registro de cada recomeço e virada.</p><div class="list">${rows.map(r=>`<button type="button" class="row-card" data-action="planning-record" data-id="${esc(r.id)}"><span class="tile-icon">${icon(r.kind==='reset'?'refresh':'calendar')}</span><span class="grow"><span class="name">${r.kind==='reset'?'Planejamento reiniciado':`${monthName(r.month)} → ${monthName(r.nextMonth)}`}</span><small>${dateText(r.date,true)}${r.status==='undone'?' · Desfeito':''}</small></span>${arrow()}</button>`).join('')}</div>`:emptyBox('🌷','Ainda não houve viradas.','Seu primeiro recomeço ou fechamento aparece aqui.'));
}
function openPlanningRecord(id){
 const r=planningRecords().find(r=>r.id===id);if(!r)return;
 const histMoney=n=>LL.fmt({preferences:{currency:r.currency||'BRL'}},n),undo=state.planning?.undo;
 let body=`<span class="badge ${r.status==='undone'?'':'green'}">${r.status==='undone'?'Desfeito':'Confirmado'} · ${dateText(r.date,true)}</span>`;
 if(r.kind==='rollover'){
  const actual=LL.monthMetrics(state,r.month),m=r.metrics;
  body+=`<div class="detail-metrics"><div><small>Entrou em ${monthName(r.month)}</small><b>${histMoney(m.incomeCents/100)}</b></div><div><small>Guardado ao confirmar</small><b>${histMoney(m.pocketCents/100)}</b></div><div><small>Usado dos cofrinhos no mês</small><b>${histMoney(m.spentCents/100)}</b></div><div><small>Pago em compromissos no mês</small><b>${histMoney(m.debtPaidCents/100)}</b></div></div><p class="fine">Fotografia do momento da confirmação. Pagamentos de compromissos podem estar incluídos nos usos dos cofrinhos; não some os dois.</p>${actual.incomeCents!==m.incomeCents||actual.spentCents!==m.spentCents||actual.debtPaidCents!==m.debtPaidCents?'<div class="alert-inline">Há lançamentos ou correções posteriores neste período. Os totais atualizados estão em Ganhos e nos históricos.</div>':''}${m.freeCents!==undefined?`<p class="fine">Livre levado para o novo mês: ${histMoney(m.freeCents/100)}. Sem novo recebimento.</p>`:''}<h3 style="margin-top:20px">Planos renovados</h3>${r.renewed.length?r.renewed.map(c=>`<div class="plan-change-row"><span class="grow"><b>${esc(c.label)}</b><small>${dateText(c.fromDate,true)} → ${dateText(c.toDate,true)}</small></span><strong>${histMoney(c.amount)}</strong></div>`).join(''):'<p class="fine">Nenhum prazo foi alterado.</p>'}`;
 }else{
  const rows=r.before.categories.filter(c=>!c.archived&&(c.targetAmount>0||c.targetDate));
  body+=`<p class="form-note" style="margin-top:16px">Planos antes do reinício. Saldos, acesso e pagamentos não foram apagados.</p>${rows.map(c=>`<div class="plan-change-row"><span class="grow"><b>${esc(c.label)}</b><small>${c.targetDate?dateText(c.targetDate,true):'Sem prazo'}</small></span><strong>${histMoney(c.targetAmount)}</strong></div>`).join('')}<p class="fine" style="margin-top:16px">Referências anteriores: ${histMoney(r.before.monthly)}/mês e ${histMoney(r.before.weekly)}/semana.</p>`;
 }
 if(undo?.id===id)body+=`<div class="list-divider">${LL.canUndoPlanning(state)?btn('Desfazer esta ação','planning-undo',id,'secondary full'):'<p class="fine">O planejamento mudou depois desta ação. A versão anterior continua registrada aqui, sem sobrescrever o plano atual.</p>'}</div>`;
 modal(r.kind==='reset'?'Antes do recomeço':`Fechamento · ${monthText(r.month)}`,body,{back:openPlanningHistory});
}

function confirmAction(title,message,label,change,{back=null,after=null}={}){modal(title,`<form id="confirmForm"><p class="form-note">${esc(message)}</p><div class="dialog-foot"><button type="submit" class="danger-button full">${label}</button></div></form>`,{back});bindForm('confirmForm',async()=>{await commit(change,{message:'Concluído.',after});});}
function openProfile(){modal('Como quer ser chamada?',`<form id="profileForm">${field('name','Seu nome',state.profile.name,'text','required minlength="2" maxlength="40" autocomplete="given-name"')}${footer('Salvar nome')}</form>`);bindForm('profileForm',async form=>{await commit(s=>{s.profile.name=form.elements.name.value.trim();},{message:'Nome salvo.'});});}
function openCurrency(){const hasValues=state.transactions.length||state.debts.length||state.allocationCategories.some(c=>c.movements.length);modal('Moeda do app',`<form id="currencyForm"><div class="field"><label for="currencySelect">Mostrar os valores em</label><select id="currencySelect" name="currency">${Object.entries(LL.CURRENCIES).map(([code,[label,symbol]])=>`<option value="${code}" ${code===state.preferences.currency?'selected':''}>${symbol} · ${label} (${code})</option>`).join('')}</select></div><div id="currencyExample" class="target-recap"><span class="label">Exemplo</span><div class="amount sm" style="margin-top:6px">${money(1234.56)}</div></div><p class="form-note" style="margin-top:16px">A moeda muda no app inteiro. Os valores não são convertidos pelo câmbio.</p>${hasValues?'<label class="check-normal"><input type="checkbox" name="confirmCurrency" required><span>Entendi: 100,00 continuam 100,00, na moeda escolhida.</span></label>':''}${footer('Salvar moeda')}</form>`);$('currencySelect').addEventListener('change',e=>{$('currencyExample').querySelector('.amount').textContent=`${LL.CURRENCIES[e.target.value][1]} 1.234,56`;});bindForm('currencyForm',async form=>{const code=form.elements.currency.value;await commit(s=>{s.preferences.currency=code;},{message:'Moeda atualizada em todo o app.'});});}
function openBackup(){modal('Backup e seus dados',`<div class="stack">${btn(icon('download')+' Baixar backup','export','','primary full')}${btn(icon('upload')+' Restaurar backup','import','','secondary full')}</div><p class="fine" style="margin-top:16px">O backup é protegido pela sua senha. Guarde uma cópia antes de trocar de celular.</p>${optionalDetails('<p>Os dados ficam neste navegador, não em uma conta na nuvem. Limpar os dados do site ou usar o modo anônimo pode apagá-los.</p><p>Backups novos incluem o cadastro necessário para restaurar em outro aparelho. Os antigos, sem esse cadastro, só abrem na instalação original.</p><p>Sem a senha e sem um backup válido, não existe recuperação automática.</p>','Sobre seus dados')}<div class="list-divider">${btn('Recomeçar do zero · perfil e dados','reset','','action-muted text-danger')}</div>`);}
async function exportBackup(){if(busy)return;busy=true;try{const data=await LLStore.backup(state),blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`life-lately-backup-${LL.today()}.json`;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);toast('Backup criptografado preparado.');}catch(e){setError(e);}finally{busy=false;}}
async function openRestoreFile(file){if(!file)return;if(file.size>15000000){toast('Esse arquivo é grande demais para um backup do app.');return;}let text;try{text=await file.text();JSON.parse(text);}catch{toast('Escolha um arquivo JSON de backup.');return;}
 modal('Restaurar seu espaço',`<form id="restoreForm"><p class="form-note">${esc(file.name)}</p>${field('password','Senha usada neste backup','','password','required autocomplete="current-password"')}<p class="fine">Vamos conferir o arquivo antes de mudar seus dados.</p>${footer('Abrir backup')}</form>`);
 bindForm('restoreForm',async form=>{busy=true;const submit=form.querySelector('[type=submit]');submit.disabled=true;submit.textContent='Conferindo…';try{const prepared=await LLStore.inspectBackup(text,form.elements.password.value);busy=false;modal('Backup encontrado',`<form id="restoreConfirmForm"><div class="restore-summary"><span class="label">${esc(prepared.state.profile.name||prepared.account.username)}</span><h3>${prepared.state.transactions.length} ganhos · ${LL.cats(prepared.state).length} cofrinhos</h3></div><p class="form-note">${state?'Os dados financeiros e o acesso deste navegador serão substituídos pelo backup.':'Seu cadastro e seus dados serão abertos neste navegador.'}</p><label class="check-normal"><input type="checkbox" required><span>Confirmo a restauração.</span></label>${footer('Restaurar backup')}</form>`);bindForm('restoreConfirmForm',async()=>{busy=true;try{const restored=await LLStore.restore(prepared);busy=false;closeModal();await showUnlocked(restored,false);toast('Seu backup foi restaurado.');}catch(e){busy=false;throw e;}});}catch(e){busy=false;submit.disabled=false;submit.textContent='Abrir backup';throw e;}});
}
function openReset(){
 modal('Recomeçar do zero',`<form id="resetForm"><p class="form-note">Seu perfil, senha, ganhos, metas, compromissos e cofrinhos desta edição serão apagados neste navegador.</p>${btn('Baixar backup antes','export','','secondary full')}${field('confirm','Digite APAGAR para confirmar','','text','required autocomplete="off" style="margin-top:8px"')}<div class="dialog-foot"><button type="submit" class="danger-button full">Apagar perfil e dados</button></div></form>`,{back:openBackup});
 bindForm('resetForm',async form=>{
  if(form.elements.confirm.value!=='APAGAR')throw Error('Digite APAGAR para confirmar.');
  busy=true;const submit=form.querySelector('[type=submit]');submit.disabled=true;submit.textContent='Apagando…';
  try{
   await LLStore.erase();busy=false;
   await lock();page='overview';monthFilter=LL.today().slice(0,7);hiddenSince=0;
   toast('Tudo zerado. Crie seu acesso para começar.');
  }catch(err){busy=false;if(submit.isConnected){submit.disabled=false;submit.textContent='Apagar perfil e dados';}throw err;}
 });
}
function openArchives(){const pockets=state.allocationCategories.filter(c=>c.archived),debts=state.debts.filter(d=>d.archived);modal('Arquivados',`<p class="form-note">O histórico continua aqui.</p>${pockets.length?`<h3>Cofrinhos</h3><div class="list" style="margin-top:12px">${pockets.map(c=>`<button class="row-card" data-action="${c.closedForDebt?'pocket-tab':'restore-pocket'}" data-tab="history" data-id="${c.id}"><span class="tile-icon">${esc(c.icon)}</span><span class="grow"><span class="name">${esc(c.label)}</span><small>${c.closedForDebt?'Quitado · ver histórico':'Toque para restaurar'}</small></span>${icon(c.closedForDebt?'chevron':'refresh')}</button>`).join('')}</div>`:''}${debts.length?`<h3 style="margin-top:20px">Compromissos</h3><div class="list" style="margin-top:12px">${debts.map(d=>`<button class="row-card" data-action="restore-debt" data-id="${esc(d.id)}"><span class="tile-icon commitment-icon">💳</span><span class="grow"><span class="name">${esc(d.name)}</span><small>${money(LL.debtBalance(state,d))} · toque para restaurar</small></span>${icon('refresh')}</button>`).join('')}</div>`:''}${!pockets.length&&!debts.length?emptyBox('🌿','Nada arquivado.',''):''}`);}
function openHelp(){const privacy=accessMode==='cloud'?'<h3>Sua conta é sincronizada.</h3><p>O acesso Google mantém os registros no projeto exclusivo do Life Lately, protegido por usuário. Uma cópia criptografada fica neste aparelho para o uso offline.</p>':accessMode==='guest'?'<h3>Você está só conhecendo.</h3><p>Os registros desta demonstração são temporários e não são enviados nem mantidos quando você sair.</p>':'<h3>Seu app é local.</h3><p>O cadastro vale neste navegador. Em outro aparelho, restaure o backup com sua senha. A senha não protege o código público do site; protege os registros locais criptografados.</p>';modal('Simples, do seu jeito.',`<div class="learn-block"><h3>1. Diga o que precisa.</h3><p>Em Organizar, crie Aluguel, Luz, Reserva… Coloque o valor e o prazo. Metas e compromissos criam seus próprios cofrinhos.</p><h3>2. Registre: Ganhei.</h3><p>Informe o dinheiro que realmente entrou. Antes de salvar, você vê exatamente quanto vai para cada cofrinho.</p><h3>3. Toque no card.</h3><p>Ali você altera o plano, registra um uso ou transfere dinheiro entre cofrinhos. Para compromissos, registre o pagamento uma única vez.</p><h3>Cofrinho completo para de receber.</h3><p>Vale também nas porcentagens manuais. O que passar do alvo vai para Livre. Em compromissos mensais, o que já foi usado neste ciclo também conta; uma nova virada renova apenas os planos escolhidos.</p><h3>Livre acompanha você.</h3><p>O saldo continua no mês seguinte. Use Distribuir Livre para aproveitar esse dinheiro sem registrá-lo outra vez em Ganhos.</p><h3>Reservar não é pagar.</h3><p>O valor destinado ao compromisso diminui o que falta reservar. Depois do pagamento real, toque em Quitei: o compromisso fica no histórico e seu cofrinho sai de Organizar.</p><h3>Seu dinheiro não muda de banco.</h3><p>São registros de organização. Separar ou pagar aqui não executa transferências bancárias.</p><h3>Os prazos orientam, não prometem.</h3><p>A divisão usa o que falta e quantos dias restam. Ela não garante renda futura. Projeções não incluem rendimentos, juros nem inflação.</p>${privacy}</div>`,{back:()=>showPage('settings')});}
async function installApp(){if(installPrompt){const p=installPrompt;await p.prompt();await p.userChoice;installPrompt=null;return;}const installed=matchMedia('(display-mode: standalone)').matches||navigator.standalone;
 modal(installed?'Já está instalado':'Leve para a tela inicial',installed?'<div class="success-note">✓ Este app já está aberto pela tela inicial.</div>':`<div class="dialog-summary"><span class="tile-icon">${icon('phone')}</span><div><h3>Life Lately no celular</h3><p class="fine">Abre como app, no seu ritmo.</p></div></div><div class="learn-block"><h3>iPhone · Safari</h3><p>Compartilhar → Adicionar à Tela de Início.</p><h3>Android · Chrome</h3><p>Menu do navegador → Instalar app ou Adicionar à tela inicial.</p></div><p class="fine" style="margin-top:19px">Abra pelo endereço HTTPS do site. A primeira abertura precisa de internet; depois, o app pode funcionar offline.</p>`);}
function openDay(iso){const items=state.transactions.filter(t=>t.date===iso);modal(dateText(iso,true),items.length?`<div class="list">${items.map(incomeRow).join('')}</div>`:'<p class="form-note">Nenhum ganho registrado nesse dia.</p>');}
const guestStore={mode:'guest',save:async raw=>{const snapshot=LL.clone(raw);LL.validate(snapshot);return{temporary:true};},lock:async()=>{},persist:async()=>({supported:false,persisted:false})};
function cloudLocked(){try{return sessionStorage.getItem(CLOUD_LOCK_KEY)==='1';}catch{return false;}}
function setCloudLocked(value){try{if(value)sessionStorage.setItem(CLOUD_LOCK_KEY,'1');else sessionStorage.removeItem(CLOUD_LOCK_KEY);}catch{}}
function providerMark(kind){return kind==='google'?'<span class="provider-mark google-mark" aria-hidden="true"><svg viewBox="0 0 24 24"><path fill="#4285F4" d="M21.6 12.2c0-.7-.1-1.4-.2-2H12v3.9h5.4a4.6 4.6 0 0 1-2 3v2.5h3.3c1.9-1.8 2.9-4.4 2.9-7.4Z"/><path fill="#34A853" d="M12 22c2.7 0 5-.9 6.7-2.4l-3.3-2.5c-.9.6-2.1 1-3.4 1a5.9 5.9 0 0 1-5.6-4.1H3v2.6A10 10 0 0 0 12 22Z"/><path fill="#FBBC05" d="M6.4 14a6 6 0 0 1 0-3.9V7.5H3a10 10 0 0 0 0 9.1L6.4 14Z"/><path fill="#EA4335" d="M12 6.1c1.5 0 2.8.5 3.8 1.5l2.9-2.8A9.7 9.7 0 0 0 3 7.5l3.4 2.6A5.9 5.9 0 0 1 12 6.1Z"/></svg></span>':'<span class="provider-mark apple-mark" aria-hidden="true"><svg viewBox="0 0 24 24" fill="currentColor"><path d="M17.1 12.5c0-2.4 2-3.6 2.1-3.7a4.6 4.6 0 0 0-3.6-1.9c-1.5-.2-3 .9-3.8.9-.8 0-2-1-3.3-.9a4.9 4.9 0 0 0-4.1 2.5c-1.8 3-.5 7.5 1.2 10 .8 1.2 1.8 2.5 3.1 2.4 1.2-.1 1.7-.8 3.2-.8s1.9.8 3.2.8c1.3 0 2.2-1.2 3-2.4.9-1.4 1.3-2.8 1.3-2.9-.1 0-3.3-1.3-3.3-4Zm-2.5-7.2c.7-.9 1.2-2.1 1.1-3.3-1 .1-2.3.7-3 1.6a4.5 4.5 0 0 0-1.1 3.2c1.2.1 2.3-.6 3-1.5Z"/></svg></span>';}
async function openGuest(){
 const demo=LL.empty();demo.profile.name='Visitante';
 await showUnlocked(demo,false,{mode:'guest',store:guestStore});
 toast('Modo conhecer: nada será salvo quando você sair.');
}
async function openCloudSession(session){
 if(!session?.user)throw Error('Sua sessão Google expirou. Entre novamente.');
 busy=true;setCloudLocked(false);
 $('access').hidden=false;$('access').innerHTML=`<div class="access-card access-loading"><div class="brand">${brand()}</div><p class="loading">Sincronizando seu espaço…</p></div>`;
 try{
  const store=LLCloud.createStore(session.user),cloudState=await store.load();
  busy=false;await showUnlocked(cloudState,false,{mode:'cloud',store,user:session.user});
 }catch(error){busy=false;renderAccess();throw error;}
}
function openCloudAccount(){
 const status=activeStore.status?.()||{},email=cloudUser?.email||'Conta Google',syncText=status.pending?'Há alterações aguardando internet.':navigator.onLine?'Tudo sincronizado.':'Você está offline. A cópia deste aparelho continua disponível.';
 modal('Conta e sincronização',`<div class="account-summary">${providerMark('google')}<div><b>${esc(cloudUser?.user_metadata?.full_name||cloudUser?.user_metadata?.name||state.profile.name||'Life Lately')}</b><small>${esc(email)}</small></div></div><div class="${status.pending?'alert-inline':'success-note'}">${status.pending?'○':'✓'} ${syncText}</div><div class="stack cloud-actions">${status.pending?btn(icon('refresh')+' Sincronizar agora','cloud-sync','','primary full'):''}${btn('Sair da conta Google','cloud-signout','','secondary full')}</div><p class="fine" style="margin-top:16px">Este projeto e suas cotas são separados do Osyra. Nenhum dado é compartilhado entre os aplicativos.</p>`);
}
function openCloudSignOut(){
 modal('Sair da conta Google?',`<form id="cloudSignOutForm"><p class="form-note">A sessão e a cópia offline serão removidas deste aparelho. Seus dados sincronizados continuarão seguros na sua conta.</p><div class="dialog-foot"><button type="submit" class="danger-button full">Sair neste aparelho</button></div></form>`,{back:openCloudAccount});
 bindForm('cloudSignOutForm',async()=>{busy=true;try{await globalThis.LLCloud.signOut(cloudUser?.id);setCloudLocked(false);busy=false;closeModal();$('view').innerHTML='';$('sidebar').innerHTML='';$('topbar').innerHTML='';$('mobileNav').innerHTML='';renderAccess();toast('Você saiu da conta Google neste aparelho.');}catch(error){busy=false;throw error;}});
}
function openGuestInfo(){modal('Modo conhecer',`<div class="learn-block"><h3>Uma demonstração segura</h3><p>Você pode explorar todas as telas sem criar conta. Os dados ficam somente na memória desta visita e desaparecem ao sair.</p><h3>Quer continuar depois?</h3><p>Volte à tela de acesso e entre com Google ou crie um acesso local.</p></div>${btn('Voltar à tela de acesso','lock','','primary full')}`);}
function renderAccess(){
 state=null;activeStore=LLStore;accessMode='local';cloudUser=null;$('shell').hidden=true;$('access').hidden=false;document.title='Life Lately · seu espaço';
 const account=LLStore.readAccount(),exists=!!account,cloudSession=globalThis.LLCloud?.session?.(),cloudSettings=globalThis.LLCloud?.settings?.()||{},native=!!globalThis.LLPlatform?.native,googleReady=!!cloudSession||(!native&&cloudSettings.googleEnabled);
 const googleExtra=googleReady?'':'disabled aria-disabled="true" title="Configuração final em andamento"';
 $('access').innerHTML=`<div class="access-card"><div class="brand">${brand()}</div><span class="kicker">${exists?'Seu espaço está aqui':'Um espaço só seu'}</span><h1 style="margin-top:9px">${exists?`Olá, ${esc(account.username.split(' ')[0])}.`:'Seu dinheiro.<br>Seus próximos planos.'}</h1><p class="subtitle">Entre, continue localmente ou apenas conheça.</p><div id="accessError" class="error" role="alert" hidden></div><div class="provider-stack"><button type="button" class="provider-button google" data-action="google-login" ${googleExtra}>${providerMark('google')}<span>${cloudSession?'Continuar com Google':'Entrar com Google'}</span>${!googleReady?'<small>configuração final</small>':''}</button><button type="button" class="provider-button apple" disabled aria-disabled="true">${providerMark('apple')}<span>Entrar com Apple</span><small>em breve</small></button>${btn(icon('eye')+' Apenas conhecer','guest-login','','secondary full')}</div><div class="access-divider"><span>${exists?'ou use sua senha deste aparelho':'ou crie um acesso local'}</span></div><form id="accessForm">${!exists?field('name','Como quer ser chamada?','','text','required minlength="2" maxlength="40" autocomplete="given-name" placeholder="Seu nome"'):''}<div class="field"><label for="accessPassword">${exists?'Sua senha':'Crie uma senha'}</label><div class="password-shell"><input id="accessPassword" name="password" type="password" required ${exists?'':'minlength="8"'} autocomplete="${exists?'current-password':'new-password'}" ${exists?'':'placeholder="Pelo menos 8 caracteres"'}>${btn('Mostrar','show-password','','')}</div></div>${!exists?field('confirm','Confirme a senha','','password','required minlength="8" autocomplete="new-password"'):''}<button type="submit" class="primary full">${exists?'Entrar neste aparelho':'Criar acesso local'}</button></form><div class="access-footer">${icon('shield')} Google sincroniza; “conhecer” não guarda dados.</div>${optionalDetails('<p>O acesso local continua protegido pela senha deste aparelho. Guarde sua senha e faça backups.</p>','Sobre as formas de acesso')}${btn('Restaurar um backup local','import','','link-button full')}</div>`;
 bindForm('accessForm',async form=>{const f=new FormData(form),pass=String(f.get('password'));if(!exists&&pass!==f.get('confirm'))throw Error('As senhas precisam ser iguais.');busy=true;const submit=form.querySelector('[type=submit]');submit.disabled=true;submit.textContent=exists?'Entrando…':'Criando…';try{const s=exists?await LLStore.unlock(pass):await LLStore.create(f.get('name'),pass);busy=false;form.reset();await showUnlocked(s,exists,{mode:'local',store:LLStore});}catch(e){busy=false;submit.disabled=false;submit.textContent=exists?'Entrar neste aparelho':'Criar acesso local';if(e?.code==='no-data'){form.reset();renderRecovery(pass);return;}throw e;}});
}
// Cadastro válido sem carga salva: despejo de armazenamento. Em vez de abrir um app
// vazio, oferecemos as duas únicas saídas honestas: restaurar backup ou recomeçar.
function renderRecovery(password){
 state=null;orphanPassword=password||'';
 $('shell').hidden=true;$('access').hidden=false;document.title='Life Lately · recuperação';
 const account=LLStore.readAccount();
 $('access').innerHTML=`<div class="access-card"><div class="brand">${brand()}</div><span class="kicker">Recuperação</span><h1 style="margin-top:9px">Seus dados não estão aqui.</h1><p class="subtitle">A senha confere, mas os registros de ${esc(account?.username||'sua conta')} não foram encontrados neste aparelho.</p><div id="accessError" class="error" role="alert" hidden></div><div class="learn-block"><h3>O que aconteceu</h3><p>O navegador ou o sistema pode ter liberado espaço apagando os dados deste app. Nada foi enviado para um servidor, então a única cópia é o backup que você guardou.</p><h3>Nada foi sobrescrito</h3><p>Não criamos um espaço vazio no lugar dos seus dados. Se o backup aparecer, ele entra por cima de nada.</p></div><div class="stack">${btn(icon('upload')+' Restaurar um backup','import','','primary full')}</div>${optionalDetails(`<p>Sem backup, os registros anteriores não têm como voltar. Você pode recomeçar do zero neste aparelho: o cadastro atual será removido e um novo acesso será criado.</p>${btn('Recomeçar do zero neste aparelho','discard-orphan','','action-muted text-danger')}`,'Não tenho backup')}</div>`;
}
function openDiscardOrphan(){
 modal('Recomeçar neste aparelho',`<form id="discardForm"><p class="form-note">Isto remove o cadastro atual deste aparelho para que você crie um acesso novo. Os registros anteriores já não estão aqui e não serão recuperados por esta ação.</p><label class="check-normal"><input type="checkbox" required><span>Entendi que não há backup para restaurar.</span></label><div class="dialog-foot"><button type="submit" class="danger-button full">Remover cadastro e recomeçar</button></div></form>`);
 bindForm('discardForm',async()=>{
  busy=true;
  try{await LLStore.discardOrphanAccount(orphanPassword);orphanPassword='';busy=false;closeModal();renderAccess();toast('Cadastro removido. Crie seu novo acesso.');}
  catch(e){busy=false;throw e;}
 });
}
async function showUnlocked(s,migrating=true,{mode='local',store=LLStore,user=null}={}){
 activeStore=store;accessMode=mode;cloudUser=user;state=s;page='overview';monthFilter=LL.planningMonth(s);orphanPassword='';
 $('access').hidden=true;$('access').innerHTML='';$('shell').hidden=false;render();
 // Regrava apenas quando a normalização migrou o esquema de verdade. Um login comum
 // não reescreve o banco: isso mantém intacta uma instalação ainda restaurável.
 if(mode==='local'&&migrating&&LLStore.wasMigrated?.()){try{await LLStore.save(state);}catch(e){toast(e.message);}}
 activeStore.persist?.();
 if(state.migrationNotes?.length)toast('Confira os dados antigos em Backup antes de fazer alterações.');
}
async function lock(){if(busy)return;busy=true;try{if(accessMode==='cloud')setCloudLocked(true);await activeStore.lock();busy=false;closeModal();$('view').innerHTML='';$('sidebar').innerHTML='';$('topbar').innerHTML='';$('mobileNav').innerHTML='';allocationDraft=null;renderAccess();}finally{busy=false;}}
async function handleAction(el){
 const action=el.dataset.action,id=el.dataset.id||'';
 switch(action){
 case 'nav':closeModal();showPage(id);break;
 case 'close':allocationDraft=null;closeModal();break;
 case 'modal-back':if(modalBack)modalBack();else closeModal();break;
 case 'new-income':openIncome();break;
 case 'income-open':openIncome(id);break;
 case 'new-pocket':pocketForm();break;
 case 'new-goal':pocketForm('','goal');break;
 case 'new-debt':newDebt();break;
 case 'pocket':openPocket(id);break;
 case 'goal-open':pocketForm(id,'goal',()=>openPocket(id));break;
 case 'pocket-tab':openPocket(id,el.dataset.tab);break;
 case 'pocket-move':openMove(id);break;
 case 'debt-open':openDebt(id);break;
 case 'debt-tab':openDebt(id,el.dataset.tab);break;
 case 'income-target':openIncomeTarget(id);break;
 case 'apply':openApply();break;
 case 'free-distribute':openFreeDistribution(id);break;
 case 'debt-settle':openSettlement(id);break;
 case 'allocation':allocationDraft=null;openAllocation();break;
 case 'allocation-mode':openAllocation(id);break;
 case 'income-delete':confirmAction('Excluir ganho?','A distribuição original também será removida. Ganhos que já foram usados nos cofrinhos não podem ser excluídos sem regularizar o saldo.','Excluir ganho',s=>LL.removeIncome(s,id),{back:()=>openIncome(id)});break;
 case 'pocket-archive':confirmAction('Arquivar cofrinho?','O histórico fica guardado. Se ainda houver dinheiro, transfira para outro cofrinho antes.','Arquivar',s=>LL.archivePocket(s,id),{back:()=>openPocket(id)});break;
 case 'debt-archive':confirmAction('Arquivar compromisso?','Isso não paga o compromisso. Seu histórico e o dinheiro do cofrinho serão preservados.','Arquivar',s=>LL.archiveDebt(s,id),{back:()=>openDebt(id)});break;
 case 'restore-pocket':await commit(s=>LL.restorePocket(s,id),{after:openArchives});break;
 case 'restore-debt':await commit(s=>LL.restoreDebt(s,id),{after:openArchives});break;
 case 'date-shortcut':{const field=$('dialog').querySelector(`[name="${el.dataset.field}"]`);if(field){field.value=LL.afterMonths(Number(id));field.dispatchEvent(new Event('change',{bubbles:true}));}break;}
 case 'pocket-template':{const f=$('pocketForm');if(f){f.elements.label.value=id;f.dataset.icon=el.dataset.emoji;f.dataset.iconPicked='1';f.querySelectorAll('[data-action=pick-emoji]').forEach(b=>b.classList.toggle('active',b.dataset.id===f.dataset.icon));}break;}
 case 'pick-emoji':{const f=$('pocketForm');if(f){f.dataset.icon=id;f.dataset.iconPicked='1';f.querySelectorAll('[data-action=pick-emoji]').forEach(b=>b.classList.toggle('active',b.dataset.id===id));}break;}
 case 'pick-color':{const f=$('pocketForm');if(f){f.dataset.color=id;f.querySelectorAll('[data-action=pick-color]').forEach(b=>b.classList.toggle('selected-color',b.dataset.id===id));}break;}
 case 'pay-all':{const input=$('payForm')?.elements.amount;if(input){input.value=numText(Number(id));input.dispatchEvent(new Event('input',{bubbles:true}));}break;}
 case 'profile':openProfile();break;
 case 'currency':openCurrency();break;
 case 'backup':openBackup();break;
 case 'google-login':{const session=globalThis.LLCloud?.session?.();if(session)await openCloudSession(session);else await globalThis.LLCloud.signInGoogle();break;}
 case 'guest-login':await openGuest();break;
 case 'cloud-account':openCloudAccount();break;
 case 'guest-info':openGuestInfo();break;
 case 'cloud-sync':{const synced=await activeStore.sync(state);state=synced.state;render();closeModal();toast(synced.changed?'Sincronização concluída.':'Tudo já estava sincronizado.');break;}
 case 'cloud-signout':openCloudSignOut();break;
 case 'export':await exportBackup();break;
 case 'import':$('backupFile').click();break;
 case 'discard-orphan':openDiscardOrphan();break;
 case 'reset':openReset();break;
 case 'planning-reset':openPlanningReset();break;
 case 'month-rollover':openMonthRollover();break;
 case 'planning-history':openPlanningHistory();break;
 case 'planning-record':openPlanningRecord(id);break;
 case 'planning-undo':openPlanningUndo(id);break;
 case 'planning-resume':await commit(s=>{const c=LL.cat(s,id);if(c){c.planningPaused=false;s.preferences.autoConfigured=true;LL.recordActivity(s,'planning',id,`Plano retomado · ${c.label}`,0,0,'','configure');}},{after:()=>openPocket(id,'plan')});break;
 case 'archives':openArchives();break;
 case 'help':openHelp();break;
 case 'install':await installApp();break;
 case 'lock':await lock();break;
 case 'day':openDay(id);break;
 case 'show-password':{const input=$('accessPassword');if(input){const show=input.type==='password';input.type=show?'text':'password';el.textContent=show?'Ocultar':'Mostrar';}break;}
 case 'update':if(swWaiting){closeModal();swWaiting.postMessage({type:'SKIP_WAITING'});}else toast('Esta é a versão disponível.');break;
 }
}
// Um WebView desatualizado faria o app abrir em tela branca sem explicação alguma.
// minSdk não garante versão de WebView no Android, então a checagem é em tempo de
// execução e diz o que fazer, em vez de falhar em silêncio.
function missingCapabilities(){
 const faltando=[];
 if(!globalThis.crypto?.subtle)faltando.push('criptografia segura');
 if(!('indexedDB'in globalThis))faltando.push('armazenamento local');
 if(typeof structuredClone!=='function')faltando.push('cópia de dados');
 if(typeof HTMLDialogElement==='undefined'||!HTMLDialogElement.prototype.showModal)faltando.push('janelas do app');
 return faltando;
}
function renderUnsupported(faltando){
 $('shell').hidden=true;$('access').hidden=false;
 const nativo=globalThis.LLPlatform?.native;
 $('access').innerHTML=`<div class="access-card"><div class="brand">${brand()}</div><span class="kicker">Aparelho</span><h1 style="margin-top:9px">Este aparelho ainda não consegue abrir o app.</h1><p class="subtitle">Faltam recursos básicos: ${esc(faltando.join(', '))}.</p><div class="learn-block"><h3>Como resolver</h3><p>${nativo?'Atualize o <b>Android System WebView</b> e o <b>Google Chrome</b> pela Play Store e abra o app de novo.':'Atualize o navegador para a versão mais recente, ou abra o app pelo endereço HTTPS em vez de um arquivo local.'}</p><h3>Seus dados</h3><p>Nada foi alterado. Se você já tinha registros neste aparelho, eles continuam onde estavam.</p></div></div>`;
}
async function registerWorker(){
 // No app nativo os arquivos já vivem no bundle: não há cache a instalar nem a invalidar.
 if(globalThis.LLPlatform?.bundled||location.protocol==='file:'||document.querySelector('meta[name=ll-preview]')||!('serviceWorker'in navigator))return;
 try{const registration=await navigator.serviceWorker.register(new URL('../sw.js',location.href),{scope:new URL('../',location.href).pathname,updateViaCache:'none'});function found(worker){swWaiting=worker;if(state){if(page==='settings')render();toast('Uma atualização está pronta em Configurações.');}}if(registration.waiting)found(registration.waiting);registration.addEventListener('updatefound',()=>{const w=registration.installing;if(w)w.addEventListener('statechange',()=>{if(w.state==='installed'&&navigator.serviceWorker.controller)found(registration.waiting||w);});});registration.update().catch(()=>{});let reloaded=false;navigator.serviceWorker.addEventListener('controllerchange',()=>{if(swWaiting&&!reloaded){reloaded=true;location.reload();}});}catch(e){console.warn('Instalação offline indisponível',e.message);}
}
document.addEventListener('DOMContentLoaded',async()=>{
 document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el||el.disabled)return;e.preventDefault();if(busy)return;try{await handleAction(el);}catch(err){setError(err);}});
 document.addEventListener('change',e=>{if(e.target.id==='monthFilter'){monthFilter=e.target.value;render();}});
 $('backupFile').addEventListener('change',async e=>{const file=e.target.files?.[0];e.target.value='';await openRestoreFile(file);});
 $('dialog').addEventListener('keydown',e=>{if(e.key!=='Tab')return;const d=$('dialog');const stops=[...d.querySelectorAll('button:not([disabled]),input:not([disabled]):not([type=hidden]),select:not([disabled]),textarea:not([disabled]),a[href],summary,[tabindex="0"]')].filter(x=>x.getClientRects().length&&!x.closest('[hidden]'));if(!stops.length){e.preventDefault();$('dialogTitle').focus();return;}const first=stops[0],last=stops.at(-1),active=document.activeElement;if(e.shiftKey&&(active===first||!stops.includes(active))){e.preventDefault();last.focus();}else if(!e.shiftKey&&(active===last||!stops.includes(active))){e.preventDefault();first.focus();}});
 $('dialog').addEventListener('cancel',e=>{e.preventDefault();if(!busy){allocationDraft=null;closeModal();}});
 document.addEventListener('visibilitychange',()=>{if(document.hidden)hiddenSince=Date.now();else if(state&&hiddenSince&&Date.now()-hiddenSince>300000)lock();});
 window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;});
 window.addEventListener('appinstalled',()=>{installPrompt=null;toast('Life Lately instalado.');});
 window.addEventListener('online',()=>{if(state)renderShell();});window.addEventListener('offline',()=>{if(state)renderShell();});
 const faltando=missingCapabilities();
 if(faltando.length){renderUnsupported(faltando);return;}
 try{
  const cloud=await globalThis.LLCloud?.init?.();
  if(cloud?.session&&!cloudLocked())await openCloudSession(cloud.session);else renderAccess();
 }catch(error){renderAccess();setError(error);}
 registerWorker();
});
